/* ---------- Global term dictionary ----------
 * Fields: term, ipa, en, zh, ex, cat, m (surface forms for inline highlighting)
 */
window.TERMS = {

  states_attorney: { term:"state's attorney", ipa:"/steɪts əˈtɜːrni/", cat:"Criminal Procedure",
    en:"The public prosecutor who brings criminal charges on behalf of the state within a county; in Illinois the office is elected, which gives the holder very broad and largely unreviewable charging discretion.",
    zh:"州检察官：代表州政府在一个郡的范围内提起刑事指控的检察官；在伊利诺伊州该职位由民选产生，因此享有极宽、几乎不受司法审查的指控裁量权。",
    ex:"Our client was charged only after the elected prosecutor reviewed the arresting officer's report.", m:["state's attorney", "state's attorney's office"] },
  preliminary_hearing: { term:"preliminary hearing", ipa:"/prɪˈlɪmɪneri ˈhɪrɪŋ/", cat:"Criminal Procedure",
    en:"An early court proceeding at which a judge decides whether the prosecution has shown probable cause to hold the defendant for further proceedings; it is a screening device, not a trial on guilt.",
    zh:"预审听证：审前由法官判断控方是否已证明合理根据、足以将被告移送后续程序的听证；它只是过滤机制，不是对罪责的审理。",
    ex:"The judge found probable cause at the preliminary hearing and bound the defendant over for trial.", m:["preliminary hearing", "preliminary hearings"] },
  probable_cause: { term:"probable cause", ipa:"/ˈprɑːbəbl kɔːz/", cat:"Criminal Procedure",
    en:"The Fourth Amendment standard for an arrest, search or charge: facts sufficient to lead a reasonable person to believe a crime was committed or that evidence will be found in the place searched.",
    zh:"合理根据：宪法第四修正案下实施逮捕、搜查或提出指控的标准，即存在足以使理性人相信犯罪已经发生或可在被搜查处发现证据的事实。",
    ex:"The officer lacked probable cause, so the items seized during the stop were suppressed.", m:["probable cause"] },
  obstruction_of_justice: { term:"obstruction of justice", ipa:"/əbˈstrʌkʃn əv ˈdʒʌstɪs/", cat:"Criminal",
    en:"A criminal offence of impeding an investigation or judicial proceeding, typically by destroying evidence, tampering with a witness or interfering with an arrest; the conduct, not the outcome, is the gravamen.",
    zh:"妨害司法罪：以毁灭证据、干扰证人或阻碍逮捕等方式妨碍侦查或审判的犯罪；构成要件着眼于行为本身，而非结果。",
    ex:"The defendant was charged with obstruction of justice after deleting files covered by subpoena.", m:["obstruction of justice", "obstructing justice"] },
  leave_of_court: { term:"leave of the court", ipa:"/liːv əv kɔːrt/", cat:"Litigation",
    en:"Permission the judge must grant before a party takes a step the rules do not allow as of right, such as adding a charge or amending a pleading after the deadline.",
    zh:"经法院许可：当事人在规则未赋予当然权利时，须先取得法官准许才能实施某项诉讼行为，如逾期追加指控或补正诉状。",
    ex:"The prosecutor sought leave of court to add a count after the filing deadline had passed.", m:["leave of the court", "leave of court"] },
  forfeiture: { term:"forfeiture", ipa:"/ˈfɔːrfɪtʃər/", cat:"Criminal Procedure",
    en:"Government seizure of property connected with criminal activity; in civil forfeiture the proceeding is against the property itself, so an owner can lose assets without ever being convicted.",
    zh:"没收：政府对与犯罪相关财产的扣押；民事没收直接针对物本身提起诉讼，因此所有权人即使从未被定罪也可能丧失财产。",
    ex:"The state pursued forfeiture of the vehicle although our client was never convicted of any offence.", m:["forfeiture"] },
  profiling: { term:"profiling", ipa:"/ˈproʊfaɪlɪŋ/", cat:"Constitutional",
    en:"Using race, ethnicity or another protected characteristic as a substitute for particularised suspicion when stopping or searching; challenged under equal protection and under Fourth Amendment reasonableness.",
    zh:"画像执法：以种族、族裔等受保护特征替代具体嫌疑实施拦截或搜查，可依平等保护条款与第四修正案的合理性标准提出挑战。",
    ex:"The stop was challenged as profiling because the officer articulated no particularised suspicion.", m:["profiling"] },
  bankruptcy: { term:"bankruptcy", ipa:"/ˈbæŋkrʌptsi/", cat:"Business",
    en:"A federal proceeding in which an insolvent debtor obtains relief from creditors through liquidation or court-supervised reorganisation, with an automatic stay freezing collection the moment the petition is filed.",
    zh:"破产：无力清偿的债务人通过清算或法院监督下的重整获得债务救济的联邦程序，提交申请的瞬间即产生自动中止，冻结债权人的追偿。",
    ex:"The company entered bankruptcy after losing its largest client and defaulting on a balloon payment.", m:["bankruptcy"] },
  liquidation: { term:"liquidation", ipa:"/ˌlɪkwɪˈdeɪʃn/", cat:"Business",
    en:"Converting a debtor's assets into cash and distributing the proceeds to creditors in statutory order; for a firm it means shut-down and dissolution rather than continued trading.",
    zh:"清算：将债务人资产变现并按法定顺序分配给债权人；对事务所而言意味着解散关闭，而不是继续经营。",
    ex:"Liquidation would leave nothing for unsecured creditors once the bank is paid.", m:["liquidation", "liquidate"] },
  trustee: { term:"trustee", ipa:"/trʌˈstiː/", cat:"Business",
    en:"A court-appointed fiduciary who oversees a reorganising debtor and may review or veto significant decisions such as accepting new engagements or incurring new debt.",
    zh:"破产受托人：法院指定的独立受信人，监督重整中的债务人，并可审查乃至否决承接新业务、举借新债等重大决策。",
    ex:"The trustee must approve the engagement letter before the firm may accept the new matter.", m:["trustee"] },
  arms_length: { term:"arm's length", ipa:"/ɑːrmz leŋθ/", cat:"Business",
    en:"A dealing between parties with no relationship or community of interest, so the terms reflect market value and are free of self-dealing or hidden control.",
    zh:"公平独立交易：各方之间不存在关联关系或共同利益、条款反映市场公允价值的交易，用以排除利益输送与隐性控制。",
    ex:"The bid was kept at arm's length to avoid any appearance of collusion or undisclosed control.", m:["arm's length", "arm's-length"] },
  suspension: { term:"suspension", ipa:"/səˈspenʃn/", cat:"Profession",
    en:"A disciplinary sanction barring a lawyer from practice for a fixed period; reinstatement usually requires proof of rehabilitation and compliance with the disciplinary order.",
    zh:"暂停执业：在一定期限内禁止律师执业的惩戒处分；期满复职通常还需证明已整改并遵守惩戒令的要求。",
    ex:"The firm reassigned the active files once the suspension of the lead partner took effect.", m:["suspension", "suspended"] },
  excessive_force: { term:"excessive force", ipa:"/ɪkˈsesɪv fɔːrs/", cat:"Torts",
    en:"Force used by a law enforcement officer beyond what a reasonable officer would consider necessary in the circumstances; it makes the seizure unreasonable and grounds a civil rights claim as well as a tort claim.",
    zh:"过度武力：警察使用的武力超出一名理性警员在当时情境下认为必要的限度，使扣押丧失合理性，可同时构成侵权与民权诉讼的诉因。",
    ex:"The officer's continued use of the weapon after the suspect was restrained raises excessive force.", m:["excessive force"] },
  leading_the_witness: { term:"leading the witness", ipa:"/ˈliːdɪŋ ðə ˈwɪtnəs/", cat:"Evidence",
    en:"Asking a question that suggests the answer the examiner wants; it is generally barred on direct examination because the testimony must be the witness's own, not counsel's.",
    zh:"诱导询问：在提问中暗示询问者期望答案的询问方式；直接询问中一般禁止，以保证证言出自证人本人而非律师。",
    ex:"Opposing counsel objected that our question was improperly leading the witness.", m:["leading the witness", "Leading the witness"] },
  redirect: { term:"redirect", ipa:"/ˌriːdəˈrekt/", cat:"Evidence",
    en:"The renewed direct examination of a witness after cross-examination, confined to matters the cross raised and used to repair or clarify the damage done.",
    zh:"再直接询问：交叉询问之后对本方证人的再次主询问，范围限于交叉所引出的事项，用以修补或澄清证言。",
    ex:"On redirect, the witness clarified the answer that opposing counsel had taken out of context.", m:["redirect"] },
  overrule: { term:"overrule", ipa:"/ˌoʊvəˈruːl/", cat:"Litigation",
    en:"To reject an objection, so the question stands and the witness may answer; the opposite ruling, upholding the objection, is to sustain it.",
    zh:"驳回（异议）：否定一方的异议，允许提问成立并由证人作答；相反的支持异议裁定称为 sustain。",
    ex:"The court overruled the objection and permitted the witness to answer the question.", m:["overrule", "overruled"] },
  discovery: { term:"discovery", ipa:"/dɪˈskʌvəri/", cat:"Litigation",
    en:"The pre-trial process by which parties obtain documents, records and witness information from each other; the wording of a request defines how far the duty to search and produce extends.",
    zh:"证据开示：审前各方相互取得文件、记录与证人信息的程序；请求的措辞决定了检索与移交义务延伸到多远。",
    ex:"Our client complied with every discovery request within the period the court ordered.", m:["discovery", "discovery requests"] },
  sanctions: { term:"sanctions", ipa:"/ˈsæŋkʃnz/", cat:"Litigation",
    en:"Penalties imposed by a court for litigation misconduct, above all for failing to produce discoverable material, ranging from costs and fees to striking claims or entering default.",
    zh:"制裁：法院对诉讼不当行为（尤其是拒不提供应开示材料）施加的处罚，从费用负担、律师费直至驳回主张或作出缺席判决。",
    ex:"The court warned that sanctions would follow if the firm withheld any further records.", m:["sanctions", "sanction"] },
  foundation: { term:"foundation", ipa:"/faʊnˈdeɪʃn/", cat:"Evidence",
    en:"The preliminary proof a proponent must lay before evidence is admitted: that an item is what it is claimed to be, that a witness has personal knowledge, or that an expert's methodology is reliable.",
    zh:"基础（铺垫）：证据被采纳前举证人须先行完成的证明，即该物确属其主张之物、证人具有亲身知悉、或专家方法可靠。",
    ex:"Counsel laid the foundation before asking the witness to identify the photograph.", m:["foundation", "foundational grounds"] },
  speculation: { term:"speculation", ipa:"/ˌspekjuˈleɪʃn/", cat:"Evidence",
    en:"Testimony that guesses at another person's state of mind or at what might have happened, without personal knowledge; it is excluded because it usurps the jury's fact-finding role.",
    zh:"推测性证言：缺乏亲身知悉而臆测他人主观状态或事件经过的证言；因僭越陪审团的事实认定职能而被排除。",
    ex:"The answer was struck as speculation because the witness had no personal knowledge.", m:["speculation", "speculate"] },
  relevance: { term:"relevance", ipa:"/ˈreləvəns/", cat:"Evidence",
    en:"The threshold requirement that evidence tend to make a fact of consequence more or less probable; relevant evidence may still be excluded on other grounds such as prejudice.",
    zh:"关联性：证据须有助于使要件事实更可能或更不可能成立的入门要求；具有关联性的证据仍可能因偏见等其他理由被排除。",
    ex:"The court excluded the earlier lawsuit as lacking relevance to this contract dispute.", m:["relevance", "Relevance", "relevant"] },
  settlement: { term:"settlement", ipa:"/ˈsetlmənt/", cat:"Litigation",
    en:"An agreement disposing of pending claims, usually for payment and a release of liability; the decision to accept or refuse an offer belongs to the client, not to counsel.",
    zh:"和解：以给付与免除责任为内容终结未决诉讼请求的协议；接受或拒绝和解方案由当事人决定，而非律师。",
    ex:"The parties reached a settlement after the court ruled on the motion to compel.", m:["settlement", "settle", "settled", "settlements"] },
  voir_dire: { term:"voir dire", ipa:"/vwɑːr ˈdɪər/", cat:"Litigation",
    en:"The examination of prospective jurors to expose bias or grounds for removal for cause, often supplemented by written questionnaires that later support a challenge if answers are untrue.",
    zh:"陪审员资格审查：对候选陪审员的询问，用以揭示偏见或有因回避的事由，常辅以书面问卷，日后可据不实回答申请剔除该陪审员。",
    ex:"The juror's answers during voir dire failed to disclose her prior involvement in similar litigation.", m:["voir dire"] },
  argumentative: { term:"argumentative", ipa:"/ˌɑːrɡjuˈmentətɪv/", cat:"Evidence",
    en:"An objection that a question is really argument addressed to the jury rather than a request for facts, as where counsel debates the witness instead of examining them.",
    zh:"争辩式提问异议：针对名为提问、实为向陪审团说理或与证人争辩的提问提出的异议。",
    ex:"The question was barred as argumentative because counsel was debating the witness rather than examining her.", m:["argumentative"] },
  subpoena: { term:"subpoena", ipa:"/səˈpiːnə/", cat:"Litigation",
    en:"A court-issued command to produce documents or testify; it carries contempt sanctions and is the standard instrument for compelling discovery from a non-party.",
    zh:"传票：法院签发的强制出庭作证或提交文件命令，不接受即以藐视法庭论处，是向第三人取证的标准工具。",
    ex:"Our client moved to compel after opposing counsel refused to answer the subpoena for business records.", m:["subpoena", "subpoenas", "subpoenaed"] },
  motion_to_quash: { term:"motion to quash", ipa:"/ˈmoʊʃn tu kwɑːʃ/", cat:"Litigation",
    en:"A request that the court annul a subpoena or other process, typically for undue burden, privilege, lack of relevance or defective service.",
    zh:"撤销申请：请求法院废止传票或其他诉讼文书，常见理由为负担过重、特权保护、缺乏关联性或送达瑕疵。",
    ex:"The defendant moved to quash the subpoena as unduly burdensome and irrelevant to any pleaded claim.", m:["motion to quash", "the subpoena be quashed", "be quashed"] },
  trade_secret: { term:"trade secret", ipa:"/treɪd ˈsiːkrət/", cat:"Business",
    en:"Business information that derives value from not being known and is subject to reasonable secrecy measures; it is protected against misappropriation but must yield to valid discovery under a protective order.",
    zh:"商业秘密：因不为公众所知悉而具有商业价值，并经权利人采取相应保密措施的信息；受侵害救济保护，但在有效保护令下仍须服从合法的证据开示。",
    ex:"The firm seeks a protective order before any trade secret is disclosed during discovery.", m:["trade secret", "trade secrets"] },
  best_evidence_rule: { term:"best evidence rule", ipa:"/best ˈevɪdəns ruːl/", cat:"Evidence",
    en:"The rule requiring the original document, recording or photograph when a party seeks to prove its content, unless a statutory excuse such as loss or destruction applies.",
    zh:"最佳证据规则：一方欲证明文书、录音、照片的内容时，原则上应提供原件，除非存在灭失、毁损等法定例外。",
    ex:"Under the best evidence rule, the witness must produce the original agreement rather than describe it.", m:["best evidence rule", "The best evidence rule"] },
  standing: { term:"standing", ipa:"/ˈstændɪŋ/", cat:"Litigation",
    en:"A plaintiff's threshold entitlement to sue, requiring injury in fact, causation and redressability; a defect is fatal and can be raised at any stage.",
    zh:"起诉资格：原告进入实体审理的前提，须具备事实上的损害、因果关系与可救济性；该缺陷可在诉讼任何阶段提出。",
    ex:"The court dismissed the claim because the plaintiff lacked standing to enforce the agreement.", m:["standing"] },
  contingency_fee: { term:"contingency fee", ipa:"/kənˈtɪndʒənsi fiː/", cat:"Profession",
    en:"A fee payable only out of recovery, aligning counsel's incentive with the client's and shifting the risk of loss to the lawyer; many jurisdictions cap the percentage and require a written agreement.",
    zh:"风险代理收费：律师报酬仅在胜诉或获赔时按约定比例收取，将败诉风险转移给律师；多数法域要求书面协议并对比例设上限。",
    ex:"Our client signed a contingency fee agreement because she could not fund hourly litigation costs.", m:["contingency fee", "on contingency", "working on contingency"] },
  first_amendment: { term:"First Amendment", ipa:"/fɜːrst əˈmendmənt/", cat:"Constitutional",
    en:"The constitutional guarantee of free speech and press, which a party may invoke to resist compelled disclosure; the claim also imports accountability for the speech protected.",
    zh:"第一修正案：宪法对言论与出版自由的保障，当事人可据此抗拒强制披露；但该主张同时意味着对其所保护的言论承担责任。",
    ex:"The defendant argued that free speech protection shields its editorial decisions from compelled disclosure.", m:["First Amendment", "free speech", "speech protections"] },
  unfair_trade_practices: { term:"unfair trade practices", ipa:"/ʌnˈfer treɪd ˈpræktɪsɪz/", cat:"Business",
    en:"A statutory cause of action covering deceptive or unconscionable marketplace conduct; pleading it usually requires showing conduct that offends public policy rather than simple breach of contract.",
    zh:"不正当竞争行为（不公平交易行为）：针对欺骗性或有违良俗的市场行为设立的法定诉由，通常须证明行为违背公共政策，而非单纯违约。",
    ex:"The complaint pleaded unfair trade practices based on the competitor's deliberately misleading advertising.", m:["unfair trade practices", "Unfair trade practices"] },
  hate_crime: { term:"hate crime", ipa:"/heɪt kraɪm/", cat:"Criminal",
    en:"An offence (or an aggravated version of one) committed with bias against a protected characteristic such as race, religion, sexual orientation or gender; the bias is an element that raises the penalty rather than creating a freestanding cause of action.",
    zh:"仇恨犯罪：基于种族、宗教、性取向或性别等受保护特征的偏见而实施的犯罪（或其加重形态）；偏见是加重刑度的构成要件，而非独立的诉因。",
    ex:"The prosecutor added a hate crime count after evidence showed the assault was motivated by bias against the victim's religion.", m:["hate crime"] },
  liability: { term:"liability", ipa:"/ˌlaɪəˈbɪləti/", cat:"Torts",
    en:"Legal responsibility for a loss or harm, giving the claimant a right to damages; in negligence it attaches once a duty of care, breach and causation are proved.",
    zh:"责任：对损失或损害承担的法律后果，使请求权人获得损害赔偿；过失责任在注意义务、违反与因果关系均证成后成立。",
    ex:"The court found the manufacturer liable after the defect caused the user's injury.", m:["liability", "liable"] },
  hearsay: { term:"hearsay", ipa:"/ˈhɪrseɪ/", cat:"Evidence",
    en:"An out-of-court statement offered to prove the truth of the matter asserted; generally inadmissible unless it falls within a recognised exception.",
    zh:"传闻证据：在法庭外作出、被提出用以证明其主张内容真实的陈述；除符合法定例外外一般不可采。",
    ex:"The judge excluded the letter as hearsay because it was offered to prove the fact it stated.", m:["hearsay", "asking for hearsay"] },
  objection: { term:"objection", ipa:"/əbˈdʒekʃn/", cat:"Evidence",
    en:"A party's formal protest to the admissibility of evidence or the propriety of a question, which the judge must rule on as sustained or overruled.",
    zh:"异议：一方对证据可采性或提问妥当性提出的正式反对，法官须裁定维持或推翻。",
    ex:"Opposing counsel raised an objection when the witness began to recount a conversation he had not witnessed.", m:["objection", "objections", "objectionable"] },
  felony: { term:"felony", ipa:"/ˈfeləni/", cat:"Criminal",
    en:"A serious crime historically punishable by death or imprisonment for more than one year, as opposed to a misdemeanour; classifications (e.g. class four) set the statutory sentencing range.",
    zh:"重罪：历史上可处死刑或一年以上监禁的严重犯罪，区别于轻罪；等级（如四级）确定法定量刑幅度。",
    ex:"The charge was reduced from a class four felony to a misdemeanour as part of the plea.", m:["felony"] },
  probation: { term:"probation", ipa:"/proʊˈbeɪʃn/", cat:"Criminal Procedure",
    en:"A sentence allowing the offender to remain in the community under supervision and conditions instead of serving time, revocable on breach.",
    zh:"缓刑：让罪犯在监督与条件下留居社区而非服刑的刑罚，违反条件即可撤销。",
    ex:"The judge sentenced the first-time offender to probation with a condition that he complete community service.", m:["probation"] },
  plaintiff: { term:"plaintiff", ipa:"/ˈpleɪntɪf/", cat:"Litigation",
    en:"The party who commences a civil action and bears the burden of proving the claimed liability; the defending party is the defendant.",
    zh:"原告：提起民事诉讼、并承担证明责任的一方；相对方为被告。",
    ex:"The plaintiff bore the burden of showing that the defendant's conduct caused the loss.", m:["plaintiff"] },
  protected_class: { term:"protected class", ipa:"/prəˈtektɪd klæs/", cat:"Constitutional",
    en:"A group shielded by anti-discrimination law (race, colour, religion, sex, national origin, and in many jurisdictions sexual orientation) so that adverse action based on membership is suspect.",
    zh:"受保护群体：受反歧视法保护的群体（种族、肤色、宗教、性别、国籍，许多法域亦含性取向），基于成员身份的不利对待将受严格审查。",
    ex:"The firm reviewed the policy to ensure it did not disadvantage any protected class.", m:["protected class"] },
  search_warrant: { term:"search warrant", ipa:"/sɜːrtʃ ˈwɔːrənt/", cat:"Criminal Procedure",
    en:"A judicial order authorising officers to search a described place and seize described items, issued on a sworn affidavit establishing probable cause; particularity is mandatory, and a general warrant is void.",
    zh:"搜查令：法官基于经宣誓的事实陈述认定存在合理根据后签发、授权侦查人员搜查特定场所并扣押特定物品的令状；必须具体描述对象，概括令状无效。",
    ex:"The court suppressed the seized records because the affidavit did not establish probable cause.", m:["search warrant", "search warrants"] },
  arrest_warrant: { term:"arrest warrant", ipa:"/əˈrest ˈwɔːrənt/", cat:"Criminal Procedure",
    en:"A judicial order directing an officer to take a named person into custody; it is required for an arrest in a home absent exigent circumstances, and it lets defence counsel demand disclosure of the evidence behind it before the first appearance.",
    zh:"逮捕令：法官签发、指令侦查人员将特定人羁押的命令；除紧急情况外，进入住宅实施逮捕必须持令，且辩方可据此在首次到庭前要求披露背后的证据。",
    ex:"Once the arrest warrant issued, the client negotiated a voluntary surrender through counsel.", m:["arrest warrant", "arrest warrants"] },
  work_product: { term:"work product", ipa:"/wɜːrk ˈprɑːdʌkt/", cat:"Evidence",
    en:"Materials prepared in anticipation of litigation by counsel or by an expert working at counsel's direction; shielded from discovery unless the opponent shows substantial need and cannot obtain the equivalent without undue hardship.",
    zh:"工作成果：律师或受律师指示的专业人员为预期诉讼所准备的材料，原则上免于证据开示；对方须证明存在重大需要且无法以其他方式取得相当内容，方可突破。",
    ex:"The firm resisted production of the accountant's notes as protected work product.", m:["work product", "work-product"] },
  bond_hearing: { term:"bond hearing", ipa:"/bɑːnd ˈhɪrɪŋ/", cat:"Criminal Procedure",
    en:"The defendant's first appearance before a judge, typically the day after arrest, at which the court decides release on recognisance, bail conditions or continued custody, often on very thin information.",
    zh:"保释听证：被告通常在逮捕次日首次到庭，由法庭决定具结释放、附条件保证金或继续羁押的程序；此时信息往往极为有限。",
    ex:"Conditions of release were fixed at the bond hearing held the morning after arrest.", m:["bond hearing", "bond hearings", "bond court"] },
  franks_motion: { term:"Franks motion", ipa:"/fræŋks ˈmoʊʃn/", cat:"Criminal Procedure",
    en:"A request to challenge the truthfulness of a warrant affidavit: the defendant must make a substantial preliminary showing that the affiant made a false statement knowingly or with reckless disregard and that the remainder of the affidavit cannot sustain probable cause; if made out, an evidentiary hearing follows.",
    zh:"Franks 动议：攻击令状所依据的宣誓陈述真实性的申请；被告须先行实质证明陈述人明知或轻率无视地作出虚假陈述，且剔除该陈述后不足以支撑合理根据，成立者可获得听证。",
    ex:"Counsel sought a hearing by showing the affiant omitted facts known to be false.", m:["Franks motion", "Franks hearing", "Franks doctrine", "franks"] },
  unseal: { term:"unseal", ipa:"/ʌnˈsiːl/", cat:"Litigation",
    en:"To lift a sealing order so that a warrant or court record becomes accessible; the movant must overcome the government's interest in confidentiality with a particularised showing of need, often on the reasoning level of Franks.",
    zh:"解封：解除封存使令状或法院记录可被查阅；申请人须以具体的必要性证明压倒政府对保密性的主张，论证强度往往可以 Franks 为标准。",
    ex:"Opposing counsel moved to unseal the warrant so the defence could test its validity.", m:["unseal", "unsealed", "unsealing"] },
  confidential_informant: { term:"confidential informant", ipa:"/ˌkɑːnfɪˈdenʃl ɪnˈfɔːrmənt/", cat:"Criminal Procedure",
    en:"A person giving information to law enforcement under an expectation of confidentiality, usually designated in documents by a number rather than a name; the government may withhold the identity unless it is material to the defence.",
    zh:"秘密线人：在保密预期下向侦查机关提供情报的人，文书中常以编号代替姓名；除对辩护具有实质意义外，政府可拒绝披露其身份。",
    ex:"The magistrate reviewed the sealed affidavit without revealing who the informant was.", m:["confidential informant", "informant", "CI", "confidential informants"] },
  obstructing_justice: { term:"obstructing justice", ipa:"/əbˈstrʌktɪŋ ˈdʒʌstɪs/", cat:"Criminal",
    en:"Impeding an investigation or proceeding by destroying evidence, lying to agents, or interfering with an arrest or search; the conduct itself is the offence, and any such interference can also defeat the confidentiality relied upon to keep a warrant sealed.",
    zh:"妨害司法：以毁灭证据、向侦查人员作虚假陈述或阻碍逮捕、搜查的方式妨碍侦查或审判的行为；处罚着眼于行为本身，且此类妨碍亦可摧毁据以密封令状的保密基础。",
    ex:"Lying to investigators about the missing files exposed the witness to a separate charge.", m:["obstructing justice", "obstruction of justice"] },
  rico: { term:"RICO", ipa:"/ˈriːkoʊ/", cat:"Criminal",
    en:"The Racketeer Influenced and Corrupt Organizations Act, which converts a pattern of racketeering activity conducted through an enterprise into a separate federal crime with heavy maximum sentences, asset forfeiture and treble civil damages.",
    zh:"RICO（《反勒索及受贿组织法》）：将通过某一「企业」实施的一系列敲诈勒索行为单独入罪的联邦法律，刑期上限极高，并附带财产没收与三倍民事赔偿。",
    ex:"Prosecutors threatened a racketeering count to pressure our client into cooperation.", m:["RICO", "rico"] },
  cease_and_desist_order: { term:"cease and desist order", ipa:"/siːs ənd dɪˈsɪst ˈɔːrdər/", cat:"Remedies",
    en:"A demand - by letter or by court order - that the recipient stop specified conduct by a stated date; it preserves the record of notice, supports a later injunction and helps establish wilfulness, but it has no coercive force of its own.",
    zh:"停止侵害令：以函件或法院命令要求相对方在特定日期前停止特定行为；其作用是固定通知事实、为日后申请禁令与主张故意性铺垫，本身并无强制执行力。",
    ex:"Before seeking an injunction, the firm demanded that the publisher stop printing the claim.", m:["cease and desist order", "cease and desist"] },
  defamation: { term:"defamation", ipa:"/ˌdefəˈmeɪʃn/", cat:"Torts",
    en:"A published false statement of fact that tends to harm reputation; the plaintiff must prove publication, falsity, fault and damage, and truth is a complete defence, which is why pre-publication fact-checking decides the exposure.",
    zh:"诽谤：向不特定第三人发布、足以损害他人名誉的虚假事实陈述；原告须证明公开传播、虚假性、过错与损害，而真实性构成完全抗辩，因此发布前的核实决定风险大小。",
    ex:"Without verification, a republished allegation may still expose the speaker to defamation.", m:["defamation", "defame", "defamatory"] },
  court_martial: { term:"court-martial", ipa:"/ˈkɔːrt ˌmɑːrʃl/", cat:"Criminal",
    en:"A criminal trial before a military tribunal under the Uniform Code of Military Justice, conducted by a panel or judge rather than a civil jury, with its own sentencing and appellate structure; subjection to it is the clearest marker that a person stands within military command.",
    zh:"军事法庭审判：依《统一军事司法法典》由军事法庭（合议庭或军事法官）而非民事陪审团审理的刑事审判，量刑与上诉自成体系；是否受其约束，是一个人是否处于军事指挥之下的最清晰标志。",
    ex:"A service member accused of desertion may still be tried by court-martial overseas.", m:["court-martial", "court-martialed", "court martial"] },
  pro_se: { term:"pro se", ipa:"/ˌproʊ ˈseɪ/", cat:"Litigation",
    en:"Representing oneself without a lawyer: the pleadings receive a more liberal construction, but the litigant remains bound by every procedural and evidentiary rule, and the court owes no legal advice.",
    zh:"自行诉讼：当事人不经律师代理而自行诉讼；其诉状会被宽容解释，但仍须遵守全部程序与证据规则，法院亦不负提供法律意见的义务。",
    ex:"Our opponent filed the complaint pro se and later refused to serve any disclosure.", m:["pro se", "pro-se"] },
  motion_to_compel: { term:"motion to compel", ipa:"/ˈmoʊʃn tə kəmˈpel/", cat:"Litigation",
    en:"An application asking the court to order compliance where the opponent has refused discovery, has answered inadequately or has asserted an unfounded privilege; most rules require a good-faith conference first and allow the court to shift expenses.",
    zh:"强制答复动议：对方拒绝证据开示、答复不充分或主张不成立的保密特权时，请求法院命令其履行的申请；多数规则要求先经善意协商，并允许法院责令负担费用。",
    ex:"The firm moved to compel after opposing counsel ignored three separate requests for production.", m:["motion to compel", "compel"] },
  discovery_request: { term:"discovery request", ipa:"/dɪˈskʌvəri rɪˈkwest/", cat:"Litigation",
    en:"A written demand served before trial - interrogatories, requests for production or admissions - that fixes the scope of pre-trial proof and gives the court something concrete to enforce if the opponent stonewalls.",
    zh:"证据开示请求：审前送达的书面要求，包括质询书、要求提供文件或自认请求；它界定审前证明的范围，也为法院提供了可由其强制的具体对象。",
    ex:"Opposing counsel served discovery requests covering every internal memorandum and electronic message.", m:["discovery request", "discovery requests", "discovery"] },
  feres_doctrine: { term:"Feres doctrine", ipa:"/ˈferəz ˈdɑːktrɪn/", cat:"Torts",
    en:"The rule barring a service member, and by extension a person deemed an arm of the military, from recovering for injuries incident to military service; it has been extended to some contractors and widely criticised as overbroad.",
    zh:"Feres 规则：禁止现役军人就「因服役而附带发生」的损害求偿、并延伸至被视为军队延伸部分的主体的规则；其适用范围已被扩张至部分承包商，因而广受批评，被认为失之过宽。",
    ex:"The negligence claim failed because the injury arose incident to active military service.", m:["Feres doctrine", "Feres v. The United States", "Feres"] },
  immunity: { term:"immunity", ipa:"/ɪˈmjuːnəti/", cat:"Litigation",
    en:"Freedom from being sued or from liability, granted for reasons of status or function rather than fault; sovereign and derivative immunity are threshold defences, so they are decided before any examination of the merits.",
    zh:"豁免：基于身份或职能而非过错，赋予主体免于被诉或免于承担责任的保护；主权豁免及其衍生的豁免属于先决抗辩，应在实体审理之前先行认定。",
    ex:"The contractor claimed derivative immunity once the records showed operational control by the military.", m:["immunity", "immune"] },
  admission_against_interest: { term:"admission against interest", ipa:"/ədˈmɪʃn əˈɡenst ˈɪntrəst/", cat:"Evidence",
    en:"A hearsay exception for a statement that was so contrary to the declarant's own penal, pecuniary or proprietary interest that a reasonable person would not have made it unless true; it is generally available only where the declarant is unavailable, while a statement offered against a party is simply an opposing party's statement and not hearsay at all.",
    zh:"不利于己的陈述：陈述作出时足以损及陈述人自身的刑事、财产或其他利益，理性人不会在虚假情况下作出的法庭外陈述，可作为传闻例外采纳；通常以陈述人无法到庭为条件，而用于对抗一方当事人的陈述应归入对方当事人的陈述，并不属于传闻。",
    ex:"A remark exposing the declarant to liability satisfied the exception and was admitted.", m:["admission against interest", "admission against penal interest", "declaration against interest"] },
  sworn_testimony: { term:"sworn testimony", ipa:"/swɔːrn ˈtestɪmoʊni/", cat:"Evidence",
    en:"Evidence given under oath or affirmation, exposing the witness to perjury if false and locking in a version that can be used later for impeachment.",
    zh:"宣誓证言：在宣誓或郑重声明下作出的证言；虚假陈述构成伪证罪，同时固定了一种可被日后弹劾使用的说法。",
    ex:"Any inconsistency between the affidavit and her sworn testimony became the basis for impeachment.", m:["sworn testimony", "testimony"] },
  co_counsel: { term:"co-counsel", ipa:"/ˈkoʊ ˌkaʊnsl/", cat:"Profession",
    en:"Another lawyer jointly representing the same client, whether inside the firm or outside it; each remains independently accountable for competent conduct and each ordinarily shares joint privilege and joint conflict analysis.",
    zh:"共同代理律师：所外或所内与另一位律师共同代理同一当事人的律师；各自的称职义务并不因分工而免除，通常也共享保密特权并须一并做利益冲突审查。",
    ex:"Co-counsel was instructed to handle discovery while the lead lawyer argued the motion.", m:["co-counsel", "co-counsels"] },
  safe_harbor: { term:"safe harbor", ipa:"/seɪf ˈhɑːrbər/", cat:"Constitutional",
    en:"A defined window in which material that would breach the standard at other hours may lawfully be broadcast, on the assumption that the audience of children is then smallest; the concept does not license everything, since obscenity stays prohibited at every hour.",
    zh:"避风港时段：监管划定的特定时段，在此期间播出其他时段会被认定为违规的内容得以合法播出，理由是推定此时未成年受众最少；该制度并非全面放行，淫秽内容在任何时段仍被禁止。",
    ex:"The regulator fined the station because the routine aired hours outside the permitted safe harbor.", m:["safe harbor", "Safe harbor", "safe harbor period"] },
  premeditation: { term:"premeditation", ipa:"/prɪˌmedɪˈteɪʃn/", cat:"Criminal",
    en:"The formation of a decision to commit the act before it is carried out; some reflection beforehand is enough, and the interval between decision and act may be very short.",
    zh:"预谋：在实施行为之前已形成实施决意；事前有一定斟酌即为已足，从决意到实行的间隔可以极为短暂。",
    ex:"The jury found beyond reasonable doubt that the killing involved premeditation rather than sudden passion.", m:["premeditation", "premeditated"] },
  liable: { term:"liable", ipa:"/ˈlaɪəbl/", cat:"Torts",
    en:"Legally answerable for a wrong or a debt, so that judgment may be entered and enforced against the party found liable; liability follows from rule and fact, not from the size of the claim.",
    zh:"承担责任：就侵权或债务负法律上的责任，因而可被作出并执行不利判决；责任源自规则与事实，而非请求金额的大小。",
    ex:"The firm argued the defendant should not be liable for losses caused by a third party's choices.", m:["liable", "liability"] },
  quash: { term:"quash", ipa:"/kwɑːʃ/", cat:"Litigation",
    en:"To annul or set aside a claim, writ, subpoena or step in a proceeding, so that it ceases to have effect; used both for killing off process that should never have issued and for disposing of an action itself.",
    zh:"撤销、宣告无效：废除请求、令状、传票或程序步骤使其失效；既可针对本不应发出的程序文书，也可针对诉讼本身。",
    ex:"The court agreed to quash the subpoena after the witness showed it was unduly burdensome.", m:["quash", "quashed"] },
  actual_damages: { term:"actual damages", ipa:"/ˈæktʃuəl ˈdæmɪdʒɪz/", cat:"Remedies",
    en:"Compensation measured by loss actually proved, as opposed to nominal or punitive damages; where none can be shown, the claim for a money judgment ordinarily fails however blameworthy the conduct.",
    zh:"实际损失赔偿：以已实际证明的损失为限的补偿，区别于名义赔偿与惩罚性赔偿；无法证明损失时，无论行为多应受谴责，金钱给付请求通常不能成立。",
    ex:"The claim failed because the defendant proved there were no actual damages from the delay.", m:["actual damages", "actual damage"] },
  venue: { term:"venue", ipa:"/ˈvenjuː/", cat:"Litigation",
    en:"The particular court or district in which a case is heard, fixed by rules on residence or where the events occurred; it is distinct from jurisdiction, and an argument made in one forum does not bind the party in another.",
    zh:"审判地：审理案件的具体法院或辖区，依法定的住所地或事件发生地规则确定；它区别于管辖权，在一处裁判场所提出的主张并不当然约束当事人在另一处的立场。",
    ex:"Opposing counsel moved to transfer the case because venue was improper in that district.", m:["venue", "another venue"] },
  Chapter_11: { term:"Chapter 11", ipa:"/ˈtʃæptər ɪˈlevn/", cat:"Business",
    en:"The reorganisation chapter of US bankruptcy law, under which the debtor keeps operating under court supervision while it restructures its debts, with a trustee or the debtor in possession directing the business.",
    zh:"第11章重整：美国破产法下的重整程序，债务人在法院监督下继续经营并重组债务，由受托人或占有中的债务人管理营业。",
    ex:"The company filed for Chapter 11 protection while it renegotiated the loan agreements with its lenders.", m:["Chapter 11"] },
  equity_partner: { term:"equity partner", ipa:"/ˈekwəti ˈpɑːrtnər/", cat:"Business",
    en:"A partner who holds an ownership share of the firm, takes a share of profit and loss and is exposed to the partnership's liabilities, as distinct from a salaried partner who merely receives income.",
    zh:"权益合伙人：持有合伙组织所有权份额、分享利润并分担亏损、且承担合伙债务风险的合伙人，区别于仅领取报酬的受薪合伙人。",
    ex:"Only an equity partner was entitled to vote on the admission of new partners.", m:["equity partner", "equity partners"] },
  severance_package: { term:"severance package", ipa:"/ˈsevərəns ˈpækɪdʒ/", cat:"Business",
    en:"The pay and benefits due to a departing partner or employee, usually fixed by contract and commonly triggered by redundancy, a sale or a change of control.",
    zh:"离职补偿方案：向离职合伙人或员工支付的薪酬与福利，通常由合同约定，并常因裁员、出售或控制权变更而触发。",
    ex:"The acquisition agreement left each departing partner's severance package to be funded by existing partners.", m:["severance package", "severance packages"] },
  nonfinancial_side_agreement: { term:"nonfinancial side agreement", ipa:"/ˌnɑːnfaɪˈnænʃl saɪd əˈɡriːmənt/", cat:"Business",
    en:"A collateral term inside a partnership contract granting a partner something other than money, such as the right to walk away on a sale or absorption; it survives even where the majority could have vetoed other amendments.",
    zh:"非金钱性质附属协议：合伙合同中赋予合伙人非金钱性权利的条款，例如在合伙被出售或吸收合并时的离职自由；即便多数方可否决其他修订，该条款依然有效。",
    ex:"Our client relied on a nonfinancial side agreement permitting immediate withdrawal after any change of control.", m:["nonfinancial side agreement", "side agreement"] },
  counsel_is_testifying: { term:"counsel is testifying", ipa:"/ˈkaʊnsl ɪz ˈtestɪfaɪɪŋ/", cat:"Evidence",
    en:"An objection that counsel has stopped asking questions and started supplying the answers, usually by loading them into a question the witness need only adopt; it is the stock response to a question that is really argument.",
    zh:"律师在代证人作证：异议理由为律师已停止提问、开始提供答案，通常把答案塞进一个证人只需附和的问题中；这是对名为提问实为论证的标准回应。",
    ex:"Opposing counsel objected that our question was improper because counsel is testifying.", m:["counsel is testifying", "Counsel is testifying", "Counsel is still testifying"] },
  state_of_mind: { term:"state of mind", ipa:"/steɪt əv maɪnd/", cat:"Evidence",
    en:"An exception allowing a statement about the speaker's then-existing intention, motive or belief, admitted to show that mental state itself and not to prove the truth of the external facts asserted.",
    zh:"主观心态：允许就陈述人当时既存的意图、动机或信念作证的传闻例外，用以证明该心理状态本身，而非证明所涉外部事实为真。",
    ex:"The letter was admitted to show the defendant's state of mind on the evening in question.", m:["state of mind", "declarant's state of mind"] },
  calls_for_narrative: { term:"calls for narrative", ipa:"/kɔːlz fɔːr ˈnærətɪv/", cat:"Evidence",
    en:"An objection that the question invites an unbroken story rather than discrete facts, leaving the other side unable to object to each assertion as it is made and the witness free to choose the shape of the tale.",
    zh:"要求叙述性回答：异议理由为提问邀请证人作连贯叙述而非陈述具体事实，使对方无法逐项即时异议，证人得以自行安排叙事结构。",
    ex:"Counsel objected that the broad question was improper because it calls for narrative.", m:["calls for narrative", "Calls for narrative"] },
  calls_for_speculation: { term:"calls for speculation", ipa:"/kɔːlz fɔːr ˌspekjuˈleɪʃn/", cat:"Evidence",
    en:"An objection that the witness is being asked to guess - about another's intent, or about what would have happened - instead of testifying to matters within personal knowledge.",
    zh:"要求推测：异议理由为提问要求证人臆测他人意图或事件可能走向，而非就亲身知悉的事实作证。",
    ex:"The question calls for speculation, so the court required proper foundation before the witness answered.", m:["calls for speculation", "Calls for speculation"] },
  in_chambers: { term:"in chambers", ipa:"/ɪn ˈtʃeɪmbərz/", cat:"Litigation",
    en:"Before the judge privately in the judge's room, away from the open court; the informality is procedural only, since anything said there is still on the record if the judge so directs.",
    zh:"在法官办公室：于法官办公室而非公开法庭上进行；不公开仅指程序形式，经法官指示，所述内容仍会完整记入笔录。",
    ex:"Counsel asked to argue the sensitive motion in chambers to avoid prejudicing the jury.", m:["in chambers", "issues conference in chambers"] },
  recuse: { term:"recuse", ipa:"/rɪˈkjuːz/", cat:"Profession",
    en:"Of a judge, to withdraw from a case because impartiality might reasonably be questioned; the initiative is the judge's own, and a refusal to step aside is normally reviewable rather than final.",
    zh:"自行回避：法官因公正性可能受到合理质疑而退出案件审理；该动议由法官本人主动作出，拒绝回避通常可被复审而非终局。",
    ex:"Opposing counsel asked the judge to recuse himself after his remarks about our client.", m:["recuse", "recuse yourself", "recusal"] },
  motion_to_substitute: { term:"motion to substitute", ipa:"/ˈmoʊʃn tuː ˈsʌbstɪtuːt/", cat:"Litigation",
    en:"An application to replace the assigned judge on the ground of prejudice, heard by a different judge on a record confined to that issue; once properly filed it divests the trial judge of further control over the case.",
    zh:"更换法官动议：以存在偏见为由申请更换主审法官的动议，由另一名法官在限于该争点的笔录范围内审理；一经合法提出，主审法官即丧失对案件的进一步控制权。",
    ex:"Filing a motion to substitute transferred the question of alleged bias to another judge for decision.", m:["motion to substitute", "substitution hearing", "motion to substitute for cause"] },
  contempt: { term:"contempt", ipa:"/kənˈtempt/", cat:"Litigation",
    en:"Conduct that obstructs the court or defies its authority, punishable summarily by fine or confinement either to compel compliance or to vindicate the court's dignity; it is the power a judge uses first when control of the courtroom is at stake.",
    zh:"藐视法庭：妨碍法庭程序或公然违抗法庭权威的行为，可当场以罚款或拘留处罚，用以强制服从或维护法庭尊严；这是法官维持庭审秩序时首先动用的权力。",
    ex:"The judge threatened the witness with contempt after she refused to answer again.", m:["contempt", "in contempt", "contempt of court"] },
  privilege: { term:"privilege", ipa:"/ˈprɪvəlɪdʒ/", cat:"Evidence",
    en:"A rule letting a party refuse to disclose, and bar another from disclosing, communications made within a protected relationship; the categories are closed, and anything outside them can be compelled however confidential it feels.",
    zh:"特权：允许当事人拒绝披露、并阻止他人披露受保护关系中交流的规则；特权类型封闭列举，不在其列者无论当事人如何信赖其私密性均可被强制披露。",
    ex:"The communication fell outside any recognised privilege, so the notes had to be produced.", m:["privilege", "privileges", "clergy privileges"] },
  actus_reus: { term:"actus reus", ipa:"/ˈæktəs ˈreɪəs/", cat:"Criminal",
    en:"The external element of an offence - a voluntary act or omission bringing about the prohibited result - which must coincide with the required state of mind before guilt can be found.",
    zh:"犯罪行为要件（客观要件）：犯罪的外部构成，即导致法定危害结果的自愿作为或不作为；须与法定犯意同时具备，方可认定有罪。",
    ex:"The prosecution still had to prove actus reus even though the defendant admitted the intent.", m:["actus reus", "Actus reus"] },
  plea_bargain: { term:"plea bargain", ipa:"/pliː ˈbɑːrɡɪn/", cat:"Criminal Procedure",
    en:"An agreement under which the accused pleads guilty, often to fewer or lesser charges, in return for a fixed or recommended sentence; unless the court accepts it, the defendant may withdraw the plea.",
    zh:"认罪协商：被告人通常就较少或较轻罪项作有罪答辩，以换取确定或建议刑期的协议；在法院接纳之前，被告人可以撤回答辩。",
    ex:"The defendant accepted a plea bargain that reduced the exposure to a fixed term of years.", m:["plea bargain", "plea bargains", "plea agreement", "plea", "plead this out"] },
  spousal_privilege: { term:"spousal privilege", ipa:"/ˈspaʊsl ˈprɪvəlɪdʒ/", cat:"Evidence",
    en:"A rule protecting confidences between spouses (marital communications privilege) and, in some jurisdictions, excusing one spouse from testifying against the other (testimonial privilege); it belongs to the spouse, not the court.",
    zh:"婚姻特权：保护配偶间保密沟通（婚姻沟通特权），并在部分法域豁免一方就对方作证的规则（作证特权）；特权归属配偶本人而非法院。",
    ex:"The defence invoked spousal privilege to block the recorded call between the husband and wife.", m:["spousal privilege", "spousal shield"] },
  defense_of_marriage_act: { term:"Defense of Marriage Act", ipa:"/dɪˈfens əv ˈmærɪdʒ ækt/", cat:"Constitutional",
    en:"A US federal statute (1996) that, before being struck down, allowed states to refuse to recognise same-sex marriages from other states and defined marriage for federal purposes as opposite-sex; a frequent flashpoint for federalism and equal-protection argument.",
    zh:"《保卫婚姻法案》：美国联邦成文法（1996），在被推翻前允许各州不承认他州同性婚姻，并将联邦意义上的婚姻定义为异性结合；常成为联邦主义与平等保护争议的焦点。",
    ex:"The brief argued that the statute denied equal protection by drawing a classification based on the couple's sex.", m:["Defense of Marriage Act", "DOMA"] },
  wiretap: { term:"wiretap", ipa:"/ˈwaɪərtæp/", cat:"Criminal Procedure",
    en:"The interception of telephone or electronic communications, which under US law generally requires a court order based on probable cause and particularity; evidence obtained without it is suppressed.",
    zh:"窃听：对电话或电子通讯的截听；在美国法下一般须基于合理根据与特定性取得法院命令，违法取得者予以排除。",
    ex:"The defence moved to suppress the recording because the wiretap was authorised after the fact.", m:["wiretap", "wiretaps"] },
  precedent: { term:"precedent", ipa:"/ˈpresɪdənt/", cat:"Litigation",
    en:"A prior decision that guides later courts under stare decisis; binding within the same jurisdiction's hierarchy and persuasive elsewhere.",
    zh:"先例：遵循先例原则下指引后续法院的先前判决；在同级管辖层级内有约束力，在其他地方具说服力。",
    ex:"The judge followed the precedent that limited the admissibility of similar evidence.", m:["precedent"] },
  impeachment: { term:"impeachment", ipa:"/ˌɪmˈpiːtʃmənt/", cat:"Evidence",
    en:"In evidence, the act of attacking a witness's credibility, typically by prior inconsistent statements, bias or conviction; distinct from the constitutional removal of an officer.",
    zh:"弹劾（证据意义上）：攻击证人可信度之举，通常借助先前不一致陈述、偏见或前科；与宪法上罢免官员不同。",
    ex:"Counsel used the prior statement to impeach the witness rather than to prove the underlying fact.", m:["impeachment"] },
  deposition: { term:"deposition", ipa:"/ˌdepəˈzɪʃn/", cat:"Litigation",
    en:"Out-of-court sworn testimony taken in question-and-answer form, usually before trial, that can later be used to impeach or, in limited cases, as evidence.",
    zh:"证言录取：审前以问答形式进行的宣誓外庭陈述，后可用来弹劾证人，或在有限情形下作为证据。",
    ex:"The witness's deposition contradicted the story he told at trial, opening him to impeachment.", m:["deposition", "depose", "depositions"] },
  character_witness: { term:"character witness", ipa:"/ˈkærəktər ˈwɪtnəs/", cat:"Evidence",
    en:"A witness called to testify to a person's reputation or trait of character; once a party 'opens the door' by putting character in issue, the opponent may rebut it.",
    zh:"品格证人：就被证人的声誉或品格特征作证的证人；一旦一方「打开大门」把品格问题提出，对方即可反驳。",
    ex:"The defence called a character witness, which let the prosecutor question the defendant's prior conduct.", m:["character witness"] },
  fruit_of_poisonous_tree: { term:"Fruit of the Poisonous Tree", ipa:"/fruːt əv ðə ˈpɔɪzənəs triː/", cat:"Constitutional",
    en:"A doctrine holding that evidence derived from an unconstitutional act (the 'tree') is itself tainted and excluded, unless a break in causation or an independent source cleanses it.",
    zh:"「毒树之果」理论：由违宪行为（毒树）衍生的证据本身亦受污染而应排除，除非因果断裂或存在独立来源予以净化。",
    ex:"Because the search was unlawful, the statements obtained from it were excluded as fruit of the poisonous tree.", m:["Fruit of the Poisonous Tree", "fruit of the poisonous tree"] },
  warrant: { term:"warrant", ipa:"/ˈwɔːrənt/", cat:"Criminal Procedure",
    en:"A written order issued by a judge or magistrate authorising an arrest, search or seizure on a showing of probable cause and particularity.",
    zh:"令状：由法官或治安法官签发的书面命令，在证明合理根据与特定性后授权逮捕、搜查或扣押。",
    ex:"The defence moved to suppress the evidence because the search was conducted without a warrant.", m:["warrant", "warrantless"] },
  attorney_client_privilege: { term:"attorney-client privilege", ipa:"/əˈtɜːrni ˈklaɪənt ˈprɪvəlɪdʒ/", cat:"Profession",
    en:"A rule keeping confidential communications between lawyer and client for the purpose of legal advice out of evidence; it belongs to the client and survives the representation, with limited exceptions.",
    zh:"律师—委托人特权：将在为提供法律意见目的下律师与委托人之间的保密沟通排除于证据之外的规则；特权归属委托人，于代理关系结束后仍存续，仅有有限例外。",
    ex:"The court quashed the subpoena because the communication was protected by attorney-client privilege.", m:["attorney client privilege", "attorney-client privilege"] },
  exhibit: { term:"exhibit", ipa:"/ɪɡˈzɪbɪt/", cat:"Evidence",
    en:"A document, object or other item formally marked and offered into evidence, identified by a letter or number and listed on the exhibit list before trial.",
    zh:"证据物：正式标记并呈交为证据的文书、物品或其他物件，以字母或编号标识，并于审前列入证据清单。",
    ex:"The contract was marked Prosecution Exhibit D and moved into evidence over the defence objection.", m:["exhibit", "exhibits"] },
  res_gestae: { term:"res gestae", ipa:"/reɪz ˈdʒestiː/", cat:"Evidence",
    en:"Latin for 'things done'; an exception letting spontaneous statements made during or immediately after an event into evidence as inherently trustworthy, outside the hearsay bar.",
    zh:"「附随事件」（拉丁文「所为之事」）：一项例外，允许把事件当时或紧接其后作出的自发陈述作为本具可信性的证据采纳，不受传闻排除。",
    ex:"The cry for help was admitted under the res gestae exception as part of the event itself.", m:["res gestae", "Res gestae"] },
  leading_question: { term:"leading question", ipa:"/ˈliːdɪŋ ˈkwestʃən/", cat:"Evidence",
    en:"A question that suggests its own answer and therefore should not be put to one's own witness on direct examination, though permitted on cross-examination.",
    zh:"诱导性提问：暗示自身答案的提问，于直接询问中不得向己方证人提出，但在交叉询问中允许。",
    ex:"The judge sustained the objection that the question was leading and rephrased it for the lawyer.", m:["leading", "leading question"] },
  verdict: { term:"verdict", ipa:"/ˈvɜːrdɪkt/", cat:"Litigation",
    en:"The formal finding of the jury (or judge in a bench trial) on the facts and, in a criminal case, on guilt; read aloud by the foreperson.",
    zh:"裁决：陪审团（或法官独任审理时由法官）就事实、在刑事案件中并就罪责作出的正式认定，由首席陪审员当庭宣读。",
    ex:"The jury returned a guilty verdict after three days of deliberation.", m:["verdict"] },
  due_process: { term:"due process", ipa:"/duː ˈprɑːses/", cat:"Constitutional",
    en:"The constitutional guarantee (Fifth and Fourteenth Amendments) of fair procedure before the government may deprive a person of life, liberty or property.",
    zh:"正当程序：宪法（第五、第十四修正案）保障的、政府在剥夺个人生命、自由或财产前须遵循的公平程序。",
    ex:"The exclusion of the evidence was defended as required by due process.", m:["due process"] },
  mediation: { term:"mediation", ipa:"/ˌmiːdiˈeɪʃn/", cat:"Litigation",
    en:"A confidential, non-binding process in which a neutral third party helps the disputants reach a voluntary settlement; commonly court-ordered before trial.",
    zh:"调解：中立第三方协助争议各方达成自愿和解的保密、无约束力程序；常由法院在审前命令进行。",
    ex:"The parties agreed to attempt mediation before the judge would set a trial date.", m:["mediation"] },
  trespass: { term:"trespass", ipa:"/ˈtrespəs/", cat:"Torts",
    en:"An unlawful entry onto another's land; in its strict (trespass ab initio or trespass to land) form it is actionable without proof of damage, and it is a frequent defence to a premises-liability claim.",
    zh:"非法侵入：对他人土地的非法进入；其严格形态（土地侵入）无需证明损害即可诉，并常为占有者责任之诉的抗辩。",
    ex:"The landowner argued the plaintiff could not recover because he had trespassed onto the property.", m:["trespass", "trespassed", "trespassing"] },
  conflict_of_interest: { term:"conflict of interest", ipa:"/ˈkɑːnflɪkt əv ˈɪntrəst/", cat:"Profession",
    en:"A situation in which a lawyer's duties to one client, or to a former client, are materially limited by the lawyer's own interests or duties to another, requiring disclosure and often consent or withdrawal.",
    zh:"利益冲突：律师对某一客户的职责，或因自身利益、或因对另一客户的职责而受到重大限制的情形，须披露，通常还需同意或退出。",
    ex:"The firm screened the lawyer after discovering a conflict of interest with a former client.", m:["conflict of interest", "conflict"] },
  attractive_nuisance: { term:"attractive nuisance", ipa:"/əˈtræktɪv ˈnuːsns/", cat:"Torts",
    en:"A doctrine imposing liability on a landowner for harm to a child drawn onto the land by a dangerous condition the child cannot appreciate; it softens the trespass defence where the entrant is very young.",
    zh:"诱引妨害：土地占有人对幼童因无法认知的危险状况而被吸引至土地上所受损害承担赔偿责任的原则；在侵入者极年幼时缓和非法侵入抗辩。",
    ex:"The court applied the attractive nuisance doctrine because the unfenced pool lured the neighbour's child.", m:["attractive nuisance"] },
  proximate_cause: { term:"proximate cause", ipa:"/ˈprɑːksɪmət kɔːz/", cat:"Torts",
    en:"The legal cause that sets a foreseeable chain of events in motion; even a factual cause is not enough unless the harm was within the scope of the risk created.",
    zh:"近因：发动可预见事件链条的法律原因；即使属事实原因，若损害不在所创设风险范围内仍不足够。",
    ex:"The defence argued the manufacturer's negligence was not the proximate cause of the remote injury.", m:["proximate cause"] },
  stipulation: { term:"stipulation", ipa:"/ˌstɪpjuˈleɪʃn/", cat:"Litigation",
    en:"A formal agreement between parties on a fact or procedure, treated as established for the case; often used to streamline trial.",
    zh:"约定（协议事项）：当事人之间就某一事实或程序达成的正式协议，在案件中视为已证成；常用于简化审理。",
    ex:"The parties entered a stipulation that the document was authentic, sparing the foundation witness.", m:["stipulation", "stipulate"] },
  arbitration: { term:"arbitration", ipa:"/ˌɑːrbɪˈtreɪʃn/", cat:"Litigation",
    en:"A private dispute-resolution process in which a neutral arbitrator (or panel) renders a binding decision instead of a court; usually consensual, faster and confidential, with very limited grounds to appeal.",
    zh:"仲裁：由中立仲裁员（或合议庭）作出有约束力决定的私密解纷程序，通常基于合意、更快且保密，上诉事由极为有限。",
    ex:"The parties agreed to resolve the dispute by arbitration rather than litigation under the contract clause.", m:["arbitration", "arbitrator"] },
  contract: { term:"contract", ipa:"/ˈkɑːntrækt/", cat:"Business",
    en:"A legally enforceable agreement creating mutual obligations; enforceable only if it has offer, acceptance, consideration and an intention to create legal relations.",
    zh:"合同：创设相互义务、具法律可执行性的协议；仅当具备要约、承诺、对价与创设法律关系之意图时方可执行。",
    ex:"The supplier breached the contract by failing to deliver the agreed quantity on time.", m:["contract", "contracts"] },
  void: { term:"void", ipa:"/vɔɪd/", cat:"Business",
    en:"Having no legal effect from the outset, as if it never existed; a void contract binds no one, unlike a voidable one which is valid until avoided.",
    zh:"无效：自始不发生法律效力，如同从未存在；无效合同对任何人无约束力，区别于在被撤销前仍有效力的可撤销合同。",
    ex:"The clause was held void because it restrained trade beyond what was reasonable.", m:["void", "voided", "voidable"] },
  chain_of_custody: { term:"chain of custody", ipa:"/tʃeɪn əv ˈkʌstədi/", cat:"Evidence",
    en:"The documented, unbroken sequence by which physical evidence is collected, handled, stored and transferred, proving it is the same item and has not been altered.",
    zh:"证据保管链：对物证进行收集、保管、储存与移送的连续书面记录，用以证明其为同一物品且未被篡改。",
    ex:"The defence attacked the chain of custody after a gap appeared in the log of who held the sample.", m:["chain of custody", "chain of custodians"] },
  burden_of_proof: { term:"burden of proof", ipa:"/ˈbɜːrdn əv pruːf/", cat:"Litigation",
    en:"The duty to prove a fact in issue; in most civil cases it rests on the claimant, while in criminal cases the prosecution must prove guilt beyond reasonable doubt.",
    zh:"举证责任：证明争议事实的责任；多数民事案件由请求权人承担，刑事案件则由控方证明排除合理怀疑的有罪。",
    ex:"The claimant bore the burden of proof that the defect caused the injury.", m:["burden of proof", "burden"] },
  appeal: { term:"appeal", ipa:"/əˈpiːl/", cat:"Litigation",
    en:"A request to a higher court to review and reverse or modify the decision of a lower court or tribunal; generally limited to errors of law or, sometimes, fact.",
    zh:"上诉：请求上级法院审查并撤销或变更下级法院或仲裁庭裁决；通常限于法律错误，有时及于事实错误。",
    ex:"After the panel ruled against them, the parties preserved their right to appeal to the Supreme Court.", m:["appeal", "appeals"] },
  three_judge_panel: { term:"three-judge panel", ipa:"/θri dʒʌdʒ ˈpænl/", cat:"Litigation",
    en:"A bench of three judges (or arbitrators) that hears a matter and decides by majority, common in appellate and arbitral tribunals.",
    zh:"三人合议庭：由三名法官（或仲裁员）组成的法庭，以多数决审理案件，常见于上诉与仲裁庭。",
    ex:"The three-judge panel ruled two to one that the award should stand.", m:["three-judge panel", "panel"] },
  bail: { term:"bail", ipa:"/beɪl/", cat:"Criminal Procedure",
    en:"The release of a defendant from custody on condition of appearing for trial, often secured by a monetary bond; a 'bail hearing' determines the terms.",
    zh:"保释：在被告承诺到庭受审的条件下将其释放，常以保证金担保；「保释听证」决定其条件。",
    ex:"The judge set bail at a level the defendant could not post, so he remained in custody.", m:["bail", "bail hearing", "bond hearing"] },
  confidential: { term:"confidential", ipa:"/ˌkɑːnfɪˈdenʃl/", cat:"Profession",
    en:"Information protected from disclosure by a duty of confidence (e.g. arbitration secrecy or the lawyer's duty to the client); its leakage can void the process or ground a sanction.",
    zh:"保密：受保密义务保护、免于披露的信息（如仲裁保密性或律师对客户的职责）；其泄露可使程序失效或构成制裁事由。",
    ex:"The tribunal treated the settlement terms as confidential and barred their use in later litigation.", m:["confidential", "confidentiality"] },
  constitutional: { term:"constitutional", ipa:"/ˌkɑːnstɪˈtjuːʃənl/", cat:"Constitutional",
    en:"Relating to the fundamental law and the limits it places on government power; a 'constitutional matter' invokes those protections and the right to a forum.",
    zh:"宪法的：关乎根本法及其对政府权力的限制；「宪法事项」援引此类保护及受审（管辖）权利。",
    ex:"Counsel framed the detention as a constitutional matter to compel a hearing that weekend.", m:["constitutional"] },
  prenuptial_agreement: { term:"prenuptial agreement", ipa:"/ˌpriːnʌpʃuəl əˈɡriːmənt/", cat:"Family",
    en:"A contract signed before marriage setting out how assets and support will be divided on divorce or death; increasingly enforceable in many US states if procedurally fair.",
    zh:"婚前协议：婚前签署、约定离婚或一方身故时财产与扶养如何分割的合同；在程序公平的前提下于许多美国州份日益可强制执行。",
    ex:"The parties signed a prenuptial agreement waiving any claim to each other's separate property.", m:["prenuptial agreement", "prenup"] },
  creditor: { term:"creditor", ipa:"/ˈkredɪtər/", cat:"Business",
    en:"A person or entity to whom a debt is owed; in insolvency the creditor's recovery depends on the priority and assets of the estate.",
    zh:"债权人：被欠债务的个人或实体；在破产中其受偿取决于债权顺位与破产财产。",
    ex:"The secured creditor objected to the plan because it impaired the lien without consent.", m:["creditor"] },
  extension: { term:"extension", ipa:"/ɪkˈstenʃn/", cat:"Litigation",
    en:"A court-approved lengthening of a deadline or a statutory period, here an extension of time to confirm a reorganization plan.",
    zh:"延期：法院批准延长的期限或法定期限，此处指延展确认重整计划的时限。",
    ex:"The judge granted a short extension to let the debtor file its amended schedules.", m:["extension"] },
  hostile_witness: { term:"hostile witness", ipa:"/ˈhɑːstaɪl ˈwɪtnəs/", cat:"Evidence",
    en:"A witness who is adverse or unwilling, whom the calling party may examine by leading questions as if on cross-examination.",
    zh:"敌意证人：怀有敌意或不情愿的证人，传唤方得以如反询问般以诱导性问题询问。",
    ex:"The court declared the employee a hostile witness after she disclaimed her own affidavit.", m:["hostile witness"] },
  witness_list: { term:"witness list", ipa:"/ˈwɪtnəs lɪst/", cat:"Litigation",
    en:"The pretrial disclosure of witnesses a party intends to call; calling someone absent from the list can be opposed as a surprise or violation of procedure.",
    zh:"证人名单：当事人在审前披露的拟传唤证人清单；传唤名单外之人可被以突袭或违反程序为由反对。",
    ex:"Opposing counsel objected because the expert was not on the exchanged witness list.", m:["witness list", "witness lists"] },
  gag_order: { term:"gag order", ipa:"/ɡæɡ ˈɔːrdər/", cat:"Litigation",
    en:"A court order restricting what parties, lawyers or the press may say publicly about a case, to protect fairness or confidentiality.",
    zh:"禁言令：法院限制当事人、律师或媒体就案件公开发言的命令，以维护公正或保密。",
    ex:"The judge entered a gag order barring either side from discussing the settlement terms.", m:["gag order", "gag orders"] },
  dismissal_with_prejudice: { term:"dismissal with prejudice", ipa:"/dɪsˈmɪsl wɪð ˈpredʒədɪs/", cat:"Litigation",
    en:"A final dismissal that bars the plaintiff from refiling the same claim; 'without prejudice' by contrast leaves the claim alive.",
    zh:"有既判力的驳回：终局性驳回，禁止原告就同一请求再次起诉；相对地，「无既判力」驳回则保留诉权。",
    ex:"The court entered a dismissal with prejudice after the plaintiff ignored two discovery orders.", m:["dismissal with prejudice", "dismissal"] },
  co_conspirator: { term:"co-conspirator", ipa:"/koʊ kənˈspɪrətər/", cat:"Criminal",
    en:"A person alleged to share the agreement and intent of a conspiracy; statements by one co-conspirator in furtherance of the plot may be admissible against the others.",
    zh:"共谋者：被指参与共谋协议与意图之人；一方共谋者为推进阴谋所作的陈述可对他人采纳。",
    ex:"The indictment named a new co-conspirator after the cooperating witness disclosed the meetings.", m:["co-conspirator", "co-conspirators"] },
  remand: { term:"remand", ipa:"/rɪˈmænd/", cat:"Criminal Procedure",
    en:"The court-ordered detention of a defendant pending trial or further proceedings, as opposed to release on bail.",
    zh:"羁押：法院命令被告在审判或后续程序前予以拘禁，相对于保释释放。",
    ex:"The judge remanded the defendant after finding no acceptable bail address.", m:["remand", "remanded"] },
  coercion: { term:"coercion", ipa:"/koʊˈɜːrʒn/", cat:"Criminal",
    en:"The use of force, threats or unlawful pressure to compel a person to act (or testify); here, threatening a witness with false information to secure testimony.",
    zh:"胁迫：以暴力、威胁或非法压力迫使他人作为（或作证）；此处指以虚假信息威胁证人以取得证词。",
    ex:"The defence argued coercion after the agent threatened the witness with a charge she knew was false.", m:["coercion"] },
  quid_pro_quo: { term:"quid pro quo", ipa:"/kwid proʊ ˈkwoʊ/", cat:"Criminal",
    en:"A 'something for something' exchange; in evidence, a benefit given to a witness conditional on their testimony that undermines credibility.",
    zh:"对价交换：以物易物式的交换；在证据法上指以作证为条件给予证人的利益，从而削弱其可信度。",
    ex:"The prosecutor's offer of leniency was a quid pro quo that wrecked the witness's reliability.", m:["quid pro quo"] },
  motion_to_dismiss: { term:"motion to dismiss", ipa:"/ˈmoʊʃn tə dɪsˈmɪs/", cat:"Litigation",
    en:"A request that the court terminate a case or charge, for lack of evidence, failure to state a claim, or violation of a right; granted, it can be with or without prejudice.",
    zh:"驳回动议：请求法院因证据不足、未陈述诉因或侵权而终止案件或指控；若获准，可具或不具既判力。",
    ex:"After the key witness was excluded, the defence filed a motion to dismiss for insufficient evidence.", m:["motion to dismiss", "dismiss"] },
  recant: { term:"recant", ipa:"/rɪˈkænt/", cat:"Evidence",
    en:"To withdraw or retract a prior statement or testimony, often after pressure; a recanting witness can undermine the prosecution's case.",
    zh:"翻供／撤回：收回或撤销先前的陈述或证词，常在受压后发生；翻供证人可削弱检方案情。",
    ex:"The witness recanted on the stand, casting doubt on the only direct evidence.", m:["recant", "recanted"] },
  inquest: { term:"inquest", ipa:"/ˈɪnkwɛst/", cat:"Criminal Procedure",
    en:"A formal inquiry, usually before a coroner (often with a jury), into the cause and circumstances of a death; it returns a conclusion, not a criminal conviction.",
    zh:"验尸调查：通常由验尸官（常配陪审团）主持、就死亡原因与情状进行的正式调查；作出结论而非刑事定罪。",
    ex:"The inquest concluded the death was accidental rather than unlawful killing.", m:["inquest", "coroner's inquest"] },
  fifth_amendment: { term:"Fifth Amendment", ipa:"/fɪfθ əˈmɛndmənt/", cat:"Constitutional",
    en:"The US constitutional clause including the privilege against self-incrimination, letting a witness refuse to answer where the answer could incriminate them.",
    zh:"第五修正案：美国宪法条款，含不自证其罪特权，允许证人在回答可能自陷于罪时拒绝作答。",
    ex:"On counsel's advice the witness invoked the Fifth Amendment and stayed silent.", m:["Fifth Amendment"] },
  motion_to_exclude: { term:"motion to exclude", ipa:"/ˈmoʊʃn tə ɪkˈskluːd/", cat:"Evidence",
    en:"A request that the court bar particular evidence from being heard, typically on grounds of unfair prejudice, lack of foundation, or privilege.",
    zh:"排除动议：请求法院禁止采纳特定证据的申请，通常基于不公平偏见、缺乏基础或特权。",
    ex:"The defence filed a motion to exclude the recording as illegally obtained.", m:["motion to exclude", "exclude"] },
  evidence: { term:"evidence", ipa:"/ˈevɪdəns/", cat:"Evidence",
    en:"Material presented to prove or disprove a fact at issue, subject to rules on relevance, reliability and exclusion; 'hard evidence' means corroborated, objective proof.",
    zh:"证据：为证明或反驳争议事实而提交的材料，受相关性、可靠性与排除规则约束；「硬证据」指经 corroborated 的客观证明。",
    ex:"The EDR data was the only hard evidence tying the vehicle to the turn.", m:["evidence"] },
  jury: { term:"jury", ipa:"/ˈdʒʊri/", cat:"Litigation",
    en:"A body of citizens sworn to determine facts and (in a trial) render a verdict; in an inquest the jury returns the conclusion on cause of death.",
    zh:"陪审团：宣誓查明事实并（于审判中）作出裁决的公民团体；验尸调查中陪审团就死因作出结论。",
    ex:"The jury was empanelled from the regular pool for the inquest.", m:["jury"] },
  suicide: { term:"suicide", ipa:"/ˈsuːɪsaɪd/", cat:"Criminal",
    en:"The act of intentionally ending one's own life; in an inquest it is a possible conclusion, now recorded in the US and (since 2013) narratively in England rather than as a formal verdict.",
    zh:"自杀：故意结束自己生命的行为；在验尸调查中为可能的结论，现于美国及（自2013年起）英格兰以叙述方式记录，而非正式「自杀」结论。",
    ex:"The defence floated a suicide theory to divert blame from the client.", m:["suicide"] },
  charges: { term:"charges", ipa:"/ˈtʃɑːrdʒɪz/", cat:"Criminal",
    en:"Formal accusations by the state that a person committed a crime; 'filing charges' begins the prosecution.",
    zh:"指控：国家就某人犯罪所提出的正式控告；「提起指控」启动追诉。",
    ex:"The inquiry did not lead to charges being filed against the surviving spouse.", m:["charges"] },
  loss_of_consortium: { term:"loss of consortium", ipa:"/lɔːs əv kənˈsɔːrʃəm/", cat:"Torts",
    en:"A derivative claim by a spouse for the loss of companionship, services and intimacy caused by an injury to the other spouse; in wrongful-death contexts it travels with the survivor's action.",
    zh:"丧失配偶权：配偶因另一方受伤害而失去陪伴、服务与亲密关系的派生请求；于过失致死情形随生存方之诉一并主张。",
    ex:"The surviving spouse added a claim for loss of consortium to the wrongful-death suit.", m:["loss of consortium"] },
  waiver: { term:"waiver", ipa:"/ˈweɪvər/", cat:"Evidence",
    en:"The voluntary relinquishment of a known right, including the intentional or inadvertent disclosure of privileged material that destroys the protection.",
    zh:"放弃：对已知权利的自愿 relinquishment，包括有意或无意披露受特权材料以致特权灭失。",
    ex:"Sharing the memo with a third party was held to be a waiver of privilege.", m:["waiver", "waived"] },
  supreme_court: { term:"Supreme Court", ipa:"/suːˈpriːm kɔːrt/", cat:"Constitutional",
    en:"The highest court of a jurisdiction, here the Illinois Supreme Court, whose seats are filled by gubernatorial appointment (subject to election); the final arbiter of state law.",
    zh:"最高法院：管辖区内最高层级的法院，此处指伊利诺伊州最高法院，其席位由州长任命（并经选举）；州法的最终裁决者。",
    ex:"The governor's nominee to the Supreme Court still faced a retention election.", m:["Supreme Court"] },
  intimidation: { term:"intimidation", ipa:"/ɪnˌtɪmɪˈdeɪʃn/", cat:"Criminal",
    en:"Conduct that causes another to fear harm or compels conduct, here used to describe improperly pressuring a prosecutor to drop charges.",
    zh:"恐吓：致使他人畏惧受害或被迫作为的行为，此处指不当施压检方撤案。",
    ex:"The defence alleged intimidation after the official leaned on the local prosecutor.", m:["intimidated", "intimidation"] },
  murder: { term:"murder", ipa:"/ˈmɜːrdər/", cat:"Criminal",
    en:"The unlawful killing of a human being with malice aforethought; the most serious homicide offence, graded into degrees in many US jurisdictions.",
    zh:"谋杀：怀恶意预谋非法杀害他人；最严重的杀人罪行，于许多美国法域分不同等级。",
    ex:"The client was found to have been murdered after the financial records surfaced.", m:["murder", "murdered"] },
  misdemeanor: { term:"misdemeanor", ipa:"/ˌmɪsdɪˈmiːnər/", cat:"Criminal",
    en:"A lesser criminal offence, punishable by up to about a year in jail, contrasted with a felony; a Class C misdemeanor is the lowest tier in Illinois.",
    zh:"轻罪：较轻的犯罪，处最高约一年监禁，与重罪相对；C 级轻罪为伊利诺伊州最低档。",
    ex:"What began as a Class C misdemeanor escalated once the strike count was applied.", m:["misdemeanor"] },
  speedy_trial: { term:"speedy trial", ipa:"/ˈspiːdi ˈtraɪəl/", cat:"Criminal Procedure",
    en:"The constitutional and statutory right to be tried without undue delay; Illinois's statute here fixes a 160-day limit after which the charge must be tried or the defendant released.",
    zh:"速审：宪法与制定法上不受不当拖延受审的权利；伊利诺伊州此法定期限为 160 天，逾期须审判或释放被告。",
    ex:"The defence invoked the speedy-trial statute to force a trial the prosecutors were stalling.", m:["speedy trial"] },
  third_strike: { term:"third strike", ipa:"/θɜːrd straɪk/", cat:"Criminal",
    en:"A repeat-offender sentencing enhancement (from 'three strikes' laws) under which a third qualifying conviction draws a drastically longer, often life, sentence.",
    zh:"三振：累犯量刑加重（源自「三振」法），第三次符合资格之定罪招致显著更长的、常为无期的刑期。",
    ex:"Because the gun charge counted as his third strike, the exposure jumped to life.", m:["third strike", "three strikes"] },
  not_guilty: { term:"not guilty", ipa:"/nɑːt ˈɡɪlti/", cat:"Criminal Procedure",
    en:"A verdict (or plea) that the prosecution failed to prove the charge beyond a reasonable doubt; it is not a finding of innocence but of insufficient proof.",
    zh:"无罪：检方未能排除合理怀疑证明指控的裁决（或答辩）；并非认定清白，而是证明不足。",
    ex:"The jury returned not guilty on the gun charge after the alibi held up.", m:["not guilty"] },
  illegally_obtained_evidence: { term:"illegally-obtained evidence", ipa:"/ɪˈliːɡəli əbˈteɪnd ˈevɪdəns/", cat:"Evidence",
    en:"Evidence gathered in violation of law or a person's rights (e.g. a warrantless hack); generally subject to exclusion for unfairness or through the exclusionary rule.",
    zh:"非法取得的证据：以违反法律或他人权利（如无证黑客入侵）方式取得的证据；通常因不公平或依排除规则而应予排除。",
    ex:"The judge refused to admit the photo as illegally-obtained evidence from a hacked account.", m:["illegally-obtained evidence", "illegally obtained"] },
  class_action: { term:"class action", ipa:"/klæs ˈækʃn/", cat:"Litigation",
    en:"A proceeding where one or few representatives sue on behalf of many similarly situated claimants, aggregating common claims for efficiency and binding the class if certified.",
    zh:"集体诉讼：由一名或少数代表为众多处境相似之请求权人起诉的程序，汇集共通请求以提升效率，经认证后对集体具约束力。",
    ex:"The court certified the class action of consumers harmed by the defective product.", m:["class action", "class actions"] },
  mistrial: { term:"mistrial", ipa:"/ˈmɪstraɪəl/", cat:"Litigation",
    en:"A trial terminated before verdict because of a fundamental defect (deadlocked jury, misconduct, prejudicial event), leaving the case to be retried or dismissed.",
    zh:"无效审判：因根本性缺陷（陪审团僵局、不当行为、偏见性事件）而在裁决前终止的审理，案件须重审或驳回。",
    ex:"The judge declared a mistrial after the juror was found to have researched the case online.", m:["mistrial"] },
  self_incrimination: { term:"self-incrimination", ipa:"/self ɪnˌkrɪmɪˈneɪʃn/", cat:"Constitutional",
    en:"The act of exposing oneself to criminal liability through one's own statements; the privilege against it lets a witness stay silent to avoid that risk.",
    zh:"自证其罪：以自身陈述使自己暴露于刑事责任；不自证其罪特权允许证人为避免该风险保持沉默。",
    ex:"The witness invoked her right against self-incrimination rather than answer the question.", m:["self-incrimination"] },
};

/* ---------- Episodes (Season 4, E01-E20) ----------
 * Each: id, ep, title, zhTitle, summary{en,zh}, themes[], scenes[{sp,t}],
 * sceneNote{en,zh}, terms[], uk{en,zh}
 */
window.EPISODES = [
  {
    id:"S04E01", ep:1, title:"I Fought the Law", zhTitle:"我与法律抗争",
    summary:{ en:"Lockhart/Gardner appears before a bankruptcy judge $60 million in debt and avoids liquidation only by accepting a court-appointed trustee. In parallel, Alicia's son is charged in a neighbouring county after a traffic stop, and she turns a preliminary hearing into a frontal attack on the county's forfeiture corridor and on the legality of the stop itself.", zh:"律所背负六千万美元债务站上破产法庭，靠接受法院指定的破产受托人才免于清算。与此同时，女主角的儿子在邻郡因一次交通拦截被指控犯罪，她把一场预审听证变成了对该郡「没收走廊」以及拦截本身合法性的正面攻击。" },
    themes:[ {en:"Bankruptcy of a professional firm: reorganisation versus liquidation, and the trustee's veto over new business.",zh:"专业机构的破产：重整与清算之争，以及受托人对承接新业务的否决权。"}, {en:"Pretextual traffic stops, profiling and civil forfeiture as a revenue model.",zh:"借口性交通拦截、画像执法，以及被当作财政来源的民事没收。"}, {en:"Prosecutorial charging discretion and the politics of the state's attorney's office.",zh:"检察官的指控裁量权与州检察官办公室的政治运作。"} ],
    scenes:[
      { sp:"Alicia Florrick", t:"it's a result of profiling." },
      { sp:"Diane Lockhart", t:"We are $60 million in debt," },
      { sp:"Alicia Florrick", t:"for the preliminary hearing." },
      { sp:"Will Gardner", t:"I was suspended from the law" },
      { sp:"Judge (Bankruptcy Court)", t:"I'd probably approve this plan," },
      { sp:"Diane Lockhart", t:"Your Honor, no one wins if you liquidate us." },
      { sp:"Nick Saverese", t:"So, I need your firm to vet them" },
      { sp:"Will Gardner", t:"at arm's length, we're fine." },
      { sp:"Diane Lockhart", t:"a trustee to supervise" },
      { sp:"Alicia Florrick", t:"Therefore, we ask this court" },
      { sp:"Alicia Florrick", t:"of no probable cause." },
      { sp:"ASA Altman", t:"it was obstruction of justice." },
      { sp:"ASA Altman", t:"leave of the court" },
      { sp:"Alicia Florrick", t:"is a forfeiture corridor," }
    ],
    sceneNote:{ en:"Two threads run in parallel: the firm's Chapter 11 survival (debt, plan approval, trustee, 'vetting' of new matters) and a criminal case built on a pretextual stop (profiling, Article 14, obstruction of justice, forfeiture). Note how Alicia converts a defensive motion into an offensive evidentiary attack on the whole county enforcement scheme.", zh:"两条线并行推进：律所的破产求生（债务、重整计划批准、受托人、新业务的「审查」）与一起建立在借口性拦截之上的刑事案件（画像执法、第14条、妨害司法、没收）。注意女主角如何把一个防御性动议转化为对全县执法模式的进攻性证据攻击。" },
    terms:[ "states_attorney", "preliminary_hearing", "probable_cause", "obstruction_of_justice", "leave_of_court", "forfeiture", "profiling", "bankruptcy", "liquidation", "trustee", "arms_length", "suspension" ],
    uk:{ en:"US prosecutors are elected 'state's attorneys' or district attorneys; in England and Wales prosecution is carried out by the appointed Crown Prosecution Service. US reorganisations are supervised by a US Trustee with the debtor usually left in possession; UK administrations are run by a licensed insolvency practitioner under the Insolvency Act 1986.", zh:"美国的公诉人多为民选的「州检察官」或地区检察官；英格兰与威尔士则由指派的皇家检控署（CPS）负责公诉。美国重整程序由联邦受托人监督、债务人通常继续经营（DIP）；英国的管理程序则由持牌破产执业人依《1986年破产法》接管。" }
  },
  {
    id:"S04E02", ep:2, title:"And the Law Won", zhTitle:"而法律获胜",
    summary:{ en:"Will tries a wrongful-death and excessive-force claim against a police officer before a judge who actively encourages jurors to submit written questions under Illinois Supreme Court Rule 243. A juror with undisclosed knowledge of the case and a discovery fight over the victim's antidepressant records drive both sides toward a settlement nobody expected at the start of trial.", zh:"男主角代理一起针对警察的致死与过度武力索赔案，主审法官依伊利诺伊州最高法院第243条规则积极鼓励陪审员书面提问。一名隐瞒案情的陪审员，加上围绕受害人抗抑郁药记录的证据开示之争，把双方推向了开庭之初谁也没预料到的和解。" },
    themes:[ {en:"Juror participation versus counsel's control of the evidentiary narrative.",zh:"陪审员的主动参与与律师对证据叙事节奏的控制之间的张力。"}, {en:"The scope of discovery: form over substance, and the sanction of withholding.",zh:"证据开示的范围之争：请求的形式与实质，以及隐匿证据的制裁后果。"}, {en:"Who decides on settlement when a creditor's representative is looking over counsel's shoulder.",zh:"当债权人代表在旁监督时，谁有权决定是否接受和解。"} ],
    scenes:[
      { sp:"Judge Bernard Temple", t:"The court may permit jurors" },
      { sp:"Judge Bernard Temple", t:"Well, I am inclined to overrule," },
      { sp:"Will Gardner", t:"Permission to redirect," },
      { sp:"Lionel Deerfield", t:"Objection. Leading the witness." },
      { sp:"Will Gardner", t:"whether we can excuse" },
      { sp:"Alicia Florrick", t:"excessive force?" },
      { sp:"Will Gardner", t:"Is Mr. Deerfield testifying?" },
      { sp:"Will Gardner", t:"Your Honor, not in evidence." },
      { sp:"Will Gardner", t:"Beyond the scope." },
      { sp:"Judge Bernard Temple", t:"on the grounds of foundation" },
      { sp:"Will Gardner", t:"with all discovery requests" },
      { sp:"Judge Bernard Temple", t:"there will be sanctions." },
      { sp:"Lionel Deerfield", t:"Objection-- argumentative." },
      { sp:"Will Gardner", t:"we have a settlement." }
    ],
    sceneNote:{ en:"A trial practice masterclass: the rhythm of objection and ruling (leading, beyond the scope, not in evidence, foundation, speculation, argumentative), the mechanics of redirect after cross, and the moment a judge moves from umpire to manager in chambers over a discovery breach. Everything is being tried to a jury that is questioning the case back.", zh:"一堂庭审实务课：异议与裁定的节奏（诱导询问、超出范围、不在证据之内、缺乏基础、推测、争辩式提问），交叉询问后再直接询问的操作，以及法官就证据开示违规在法官办公室从「裁判者」转为「管理者」的那一刻。而这一切，都在向一个反向提问本案的陪审团进行。" },
    terms:[ "excessive_force", "leading_the_witness", "redirect", "overrule", "discovery", "sanctions", "foundation", "speculation", "relevance", "settlement", "voir_dire", "argumentative" ],
    uk:{ en:"US civil juries are traditionally passive, though a growing number of states let them submit written questions to witnesses; in England and Wales a juror may only send a question through the judge, who decides whether to put it. US pre-trial 'discovery' is called 'disclosure' in England and Wales, and is far more limited in scope.", zh:"美国民事陪审团传统上是被动听审者，不过已有越来越多州允许其向证人书面提问；在英格兰与威尔士，陪审员只能经由法官转交问题，是否提出由法官决定。美国的审前「证据开示」（discovery）在英国称为 disclosure（证据披露），范围要窄得多。" }
  },
  {
    id:"S04E03", ep:3, title:"Two Girls One Code", zhTitle:"两个女孩，一个代码",
    summary:{ en:"Two independent software developers sue Chumhum, the search engine giant, after their voice-recognition app collapses from page one to page 28 of its results the moment they refuse to buy advertising. Lockhart Gardner fights to subpoena the ranking algorithm itself; Chumhum answers that the algorithm is a trade secret, and then that it is speech. The firm's bankruptcy trustee presses for a cheap settlement, while the university that hosted the coders tries to claim ownership and knock the plaintiffs out for want of standing.", zh:"两位独立开发者起诉搜索引擎巨头 Chumhum：拒绝投放广告后，其语音识别软件在搜索结果中从首页掉到第 28 页。律所力图以传票调取被告的排序算法，被告先主张算法属商业秘密，继而主张算法受言论自由保护。与此同时，破产托管人力推低价和解，开发者所属高校则试图以职务成果为由主张软件归其所有，进而否定原告的起诉资格。" },
    themes:[ {en:"Discovery of source code and ranking algorithms: trade-secret protection weighed against compelled disclosure.",zh:"源代码与排名算法的证据开示：商业秘密保护与强制披露之间的权衡。"}, {en:"Litigation leverage, timing and settlement pressure in a cash-starved firm.",zh:"资金枯竭的律所如何以谈判筹码、时机选择制造并承受和解压力。"}, {en:"Free speech and editorial discretion asserted as a shield for algorithmic ranking.",zh:"以言论自由与编辑裁量为算法排序行为提供抗辩。"}, {en:"Standing, ownership of works made on university property, and estoppel by silence.",zh:"起诉资格、校园职务成果权属与沉默禁反言。"} ],
    scenes:[
      { sp:"Viola Walsh", t:"Please ask the witness to refrain from addressing my client." },
      { sp:"Cary Agos", t:"Why don't you refrain from speaking to our clients, Mr. Gross?" },
      { sp:"Viola Walsh", t:"I'm the defendant in your current suit." },
      { sp:"Viola Walsh", t:"Your team is working on contingency." },
      { sp:"Viola Walsh", t:"You're watching out for the creditors, sir. Will isn't." },
      { sp:"Will Gardner", t:"Then, Your Honor, we subpoena Chumhum for records on their algorithm." },
      { sp:"Viola Walsh", t:"If you expose the algorithm, you expose a trade secret." },
      { sp:"Will Gardner", t:"The best evidence rule applies here, Your Honor." },
      { sp:"Judge Marx", t:"So I am prone to order such a subpoena." },
      { sp:"Will Gardner", t:"Objection, Your Honor. Relevance." },
      { sp:"Will Gardner", t:"So the rules don't apply to you?" },
      { sp:"Judge Marx", t:"I'm ready to rule on standing." },
      { sp:"Alicia Florrick", t:"They can't have their cake and eat it too, Your Honor." },
      { sp:"Judge Marx", t:"No, Ms. Walsh, she's right." }
    ],
    sceneNote:{ en:"The episode is essentially one long discovery fight. Plaintiffs must prove the algorithm changed and harmed them, so they need the algorithm itself; the defendant has no way to disprove the claim without producing the very thing it wants hidden. Watch how each side argues relevance and damages first, because the court will not order disclosure on a theory the plaintiff has not yet supported. The First Amendment answer is clever and dangerous for the defendant: by claiming editorial discretion it accepts responsibility for the content of its rankings, including the defamatory suggestions made about the plaintiffs.", zh:"本集本质是一场拉锯式的证据开示之争。原告必须证明算法被调整并造成损害，就必须拿到算法本身；被告若想反驳，又不得不亮出它最想隐藏的东西。注意双方都先把火力放在关联性与损害是否成立上——法院不会在原告尚未提出初步证据的前提下命令披露。被告的言论自由抗辩看似巧妙实则危险：一旦主张自己对搜索结果享有编辑裁量权，就等于承认要对排序内容（包括对原告的诽谤性暗示）负责。" },
    terms:[ "subpoena", "motion_to_quash", "trade_secret", "best_evidence_rule", "relevance", "standing", "preliminary_hearing", "contingency_fee", "first_amendment", "unfair_trade_practices" ],
    uk:{ en:"The best evidence rule (now Federal Rule of Evidence 1002 in its codified form) is an admissibility rule about proving the content of a writing, recording or photograph: it does not by itself create a right of discovery. Counsel here borrows it rhetorically to justify compelled production of source code. In practice courts address that problem through Rule 26 proportionality, trade-secret protective orders, and neutral-third-party or attorney-eyes-only review rather than open disclosure.", zh:"最佳证据规则解决的是文书、录音、照片内容的证明方式问题，属于可采性规则，本身并不创设证据开示请求权；剧中把它当作强制披露源代码的理由，属于修辞借力。实务中处理这类问题走的是开示比例原则、商业秘密保护令，以及由中立第三方或『仅律师可见』方式审阅，而不是直接公开。" }
  },
  {
    id:"S04E04", ep:4, title:"Don't Haze Me Bro", zhTitle:"别欺负我兄弟",
    summary:{ en:"The firm defends a university against a civil wrongful-death suit cast as a hate crime after a student drowns during a fraternity hazing ritual known as 'The Dunk'. The trial turns on civil liability, the admissibility of evidence about the victim's sexual orientation, and a barrage of hearsay and relevance objections. In a parallel thread, the firm's court-appointed trustee Clarke Hayden keeps pressing the partners over office and control, and a side matter surfaces a class-four felony prostitution charge.", zh:"律所代理一所大学，应对因兄弟会欺凌仪式「浸水」中一名学生溺亡而被定性为仇恨犯罪的民事错误致死诉讼。庭审焦点集中在民事责任、关于受害者性取向证据的可采性，以及一连串传闻与相关性异议。与此同时，法院指定的破产受托人 Clarke Hayden 持续就办公空间与控制权向合伙人施压，另一起案件还牵出四级重罪卖淫指控。" },
    themes:[ {en:"Civil liability for a hate crime: when bias motivation makes a tort defendant liable, and the limits of using a victim's sexual orientation as evidence.",zh:"仇恨犯罪的民事责任：偏见动机何时让侵权被告担责，以及把受害者性取向作为证据的边界。"}, {en:"Hearsay, objections and the judge's power to sustain, overrule and allow.",zh:"传闻证据、异议，以及法官维持、推翻与准予裁定的权力。"}, {en:"The firm's bankruptcy trustee as a continuing constraint on the partners' autonomy.",zh:"律所的破产受托人持续约束合伙人自主权的张力。"} ],
    scenes:[
      { sp:"Gene Andrews", t:"the university isn't liable" },
      { sp:"Judge", t:"I will sustain that." },
      { sp:"Diane Lockhart", t:"Objection, Your Honor. Hearsay." },
      { sp:"Judge", t:"overrule your objection." },
      { sp:"Judge", t:"I'll allow it." },
      { sp:"Alicia Florrick", t:"charged with a hate crime." },
      { sp:"Diane Lockhart", t:"Objection. Hearsay." },
      { sp:"Gene Andrews", t:"Liability is dependent on whether it's a hate crime or not." },
      { sp:"Gene Andrews", t:"Your Honor, a mannerism is not a protected class." },
      { sp:"Will Gardner", t:"the bankruptcy judge on this," },
      { sp:"Diane Lockhart", t:"Prostitution is a class four felony." },
      { sp:"Alicia Florrick", t:"This is about liability." },
      { sp:"Alicia Florrick", t:"Objection as to what Mr. Crockett saw." },
      { sp:"Judge", t:"I'll allow." }
    ],
    sceneNote:{ en:"The episode splits between a hate-crime wrongful-death trial and the firm's internal survival. Note how civil 'liability' is chained to the criminal label 'hate crime', and how the defense tries to keep evidence of the victim's sexual orientation out through hearsay and relevance objections while the judge tightly controls the record with sustained/overruled rulings.", zh:"本集在仇恨犯罪错误致死诉讼与律所内部求生之间切换。注意民事责任如何被「链式」绑定到「仇恨犯罪」这一刑事标签，以及辩方如何借助传闻与相关性异议把受害者性取向证据挡在门外，而法官通过维持/推翻裁定严密掌控庭审记录。" },
    terms:[ "hate_crime", "liability", "hearsay", "objection", "felony", "probation", "bankruptcy", "settlement", "plaintiff", "protected_class" ],
    uk:{ en:"US hate-crime enhancements are statutory (federal and state) and raise the penalty where bias motivation is proved; England and Wales instead treats hostility as an aggravating factor at sentencing under the Crime and Disorder Act 1998 rather than as a separate element of the offence. Civil liability for a death at a regulated event in the UK would be pursued as negligence or under the Occupiers' Liability Act 1957, with the corporate defendant owing a duty of care to entrants.", zh:"美国的仇恨犯罪加重处罚由联邦与州成文法设定，证明偏见动机即提高刑度；英格兰与威尔士则依《1998年犯罪与失序法》把敌意作为量刑时的加重因素，而非犯罪的独立构成要件。英国对受监管活动中死亡事件的民事责任，通常按过失或《1957年占有人责任法》主张，公司被告对进入者负有注意义务。" }
  },
  {
    id:"S04E05", ep:5, title:"Waiting for the Knock", zhTitle:"等待敲门声",
    summary:{ en:"Federal agents move against Lemond Bishop's circle: his accountant is arrested at home, a sealed federal warrant is executed on a residence, and one of Bishop's lawyers is detained during the search. Because the warrant is sealed, the defence cannot learn what it targets, so the firm files a Franks motion arguing that any arrest made in connection with the search is grounds to open it. In parallel, a political blogger threatens to publish a story about Peter Florrick, and a cease-and-desist demand backed by a defamation threat is used - badly - to keep it quiet. The episode ends with a murder case closing in on Bishop and a judge signing his arrest warrant.", zh:"联邦探员开始围剿当事人的生意圈：他的会计师在家中被捕，一份密封的联邦搜查令被执行，他的一名律师在搜查过程中被扣。由于令状被密封，辩方无从得知其指向，事务所遂提起 Franks 动议，主张凡在本次搜查中被实施的逮捕均构成解封的依据。与此同时，一名政治博客写手准备发布关于女主丈夫的传闻，一封停止侵害函配以诽谤恫吓，用得很不漂亮。剧集收尾于一桩谋杀案逼近当事人、法官签发对他的逮捕令。" },
    themes:[ {en:"Sealed warrants and the Franks doctrine: how counsel attacks an affidavit nobody is allowed to read.",zh:"密封令状与 Franks 规则：被禁止阅读的宣誓陈述，律师该如何攻击。"}, {en:"Pre-charge timing as leverage: the bond hearing comes the morning after arrest, long before the discovery ever arrives.",zh:"指控前的时间就是筹码：保释听证在逮捕次日清晨即举行，远早于任何证据开示。"}, {en:"Reputation management outside the courtroom: cease-and-desist letters, defamation threats and the cost of a lie.",zh:"法庭之外的声誉管理：停止侵害函、诽谤恫吓，以及一句谎言的代价。"} ],
    scenes:[
      { sp:"Lesli Rand", t:"any of his work product." },
      { sp:"Lesli Rand", t:"state and federal bond court." },
      { sp:"Lesli Rand", t:"Heard you were having RICO troubles," },
      { sp:"Eli Gold", t:"I need you to call a blogger and intimidate him with a cease and desist order." },
      { sp:"Will Gardner", t:"Cease and desist from what?" },
      { sp:"Will Gardner", t:"It's called defamation." },
      { sp:"Will Gardner", t:"You defame our client, Peter Florrick," },
      { sp:"Kalinda Sharma", t:"The feds had a search warrant." },
      { sp:"Diane Lockhart", t:"The warrant will only be unsealed if they arrest Lemond." },
      { sp:"Will Gardner", t:"Any arrest in connection with this search would be grounds to unseal warrant." },
      { sp:"Lana Delaney", t:"I'm here because your people filed a Franks motion to unseal the search warrant." },
      { sp:"Alicia Florrick", t:"The arrest of Mr. Agos was made during the search, Your Honor. Under the Franks doctrine, that is grounds to unseal the warrant." },
      { sp:"Judge (Franks Hearing)", t:"Agent Delaney, I am ordering the warrant unsealed." },
      { sp:"Alicia Florrick", t:"We won the Franks hearing." }
    ],
    sceneNote:{ en:"The investigative thread is a lesson in attacking what you cannot see: with the warrant sealed, counsel argues Fourth Amendment unreasonableness from the outside - an arrest of a non-target during the search - and uses Franks as the lever to force disclosure. Watch the chronology too: the bond hearing is the first and often only meaningful checkpoint after arrest, which is why the two firms argue over who covers it and over whether privileged work product has already been taken. The political thread shows the opposite failure mode: a cease-and-desist demand is only credible if counsel has actually verified the facts, and 'it's true' is not a defence the blogger, not the lawyer, has to prove.", zh:"侦查线是一堂「攻击你看不见的东西」的课：令状被密封，律师只能从外部主张第四修正案上的不合理——搜查中对非对象的逮捕——并以 Franks 作为迫使披露的杠杆。注意时间结构：保释听证是逮捕后第一个、往往也是唯一有意义的程序节点，两家事务所争的正是谁去出庭、以及受特权保护的工作成果是否已被取走。政治线则展示了相反的失败方式：停止侵害函只有在律师真正核实过事实之后才有说服力，而「这是真的」恰恰是该由博主、而不是律师去证明的抗辩。" },
    terms:[ "search_warrant", "arrest_warrant", "work_product", "bond_hearing", "franks_motion", "unseal", "confidential_informant", "obstructing_justice", "rico", "cease_and_desist_order", "defamation" ],
    uk:{ en:"In England and Wales a search warrant is issued by a magistrate under section 8 of PACE 1984, and challenges go by judicial review or by excluding the evidence under section 78, not by a Franks-style attack on the affidavit. Informants are protected through public interest immunity rather than by sealing the warrant itself, and pre-charge bail has been cut back sharply by the Policing and Crime Act 2017. A cease-and-desist letter has no statutory standing; libel practice is governed by the Defamation Act 2013 - serious harm plus truth or honest opinion - and by its own pre-action protocol.", zh:"英格兰与威尔士的搜查令由治安法官依《1984年警察与刑事证据法》第8条签发，救济途径是司法审查或依该法第78条申请排除证据，而非美国式的 Franks 攻击；线人依靠公共利益豁免（PII）获得保护，而不是把令状本身封存；审前保释则被《2017年警务与犯罪法》大幅限缩。停止侵害函在英国并无制定法地位，诽谤诉讼适用《2013年诽谤法》——须证明严重损害，并以真实性或诚实意见抗辩——并受专门的诉前议定书约束。" }
  },
  {
    id:"S04E06", ep:6, title:"The Art of War", zhTitle:"兵法",
    summary:{ en:"A judge refers an army lawyer serving in the JAG Corps who was sexually attacked on a base in Afghanistan by an employee of the private security contractor that employed her. Counsel moves to compel production of the attacker before he can be redeployed within forty-eight hours; the contractor answers with Feres v. United States, arguing that a service member cannot sue the military and therefore cannot sue an arm of it. The judge grants an expedited subpoena conditioned on proof of how closely the contractor is integrated into the chain of command, counsel proves integration through court-martial exposure - and thereby hands the defence the very fact that defeats the claim, because fifteen minutes before the attack the attacker had been called to active duty.", zh:"一名法官转介来这样的当事人：她在阿富汗基地被一家私人安保承包商的雇员性侵，本人却是军法署（JAG）的现役律师。律师申请在袭击者四十八小时内被重新部署前强制其到庭；承包商则以 Feres v. United States 回应，主张现役军人不得起诉军队，因而也不得起诉军队的延伸部分。法官以「承包商与指挥链结合的紧密程度」为条件准许加急传票，律师又以雇员受军事审判约束证明这种结合——恰恰由此把击败请求的事实交到了对方手中：袭击发生前十五分钟，袭击者已被征召转为现役。" },
    themes:[ {en:"Outsourced warfare: private contractors and the reach of the Feres bar.",zh:"外包战争：私人承包商与 Feres 规则的射程。"}, {en:"Discipline as proof of integration: court-martial exposure used to show that a contractor is an arm of the military.",zh:"以纪律证明一体化：用雇员受军事审判的连带义务，证明承包商是军队的延伸。"}, {en:"Procedural inequality between repeat players: discovery stonewalling, a 48-hour deployment window, and the self-represented party.",zh:"程序资源的不对等：拒答证据开示、四十八小时的部署窗口，以及自行出庭的一方。"} ],
    scenes:[
      { sp:"Judge Kuhn", t:"To court-martial you." },
      { sp:"Captain Hellinger", t:"I'm pursuing this pro se." },
      { sp:"Alicia Florrick", t:"You won't win the motion." },
      { sp:"Alicia Florrick", t:"Well, this is a motion for Martinel Security to present your attacker in court for questioning?" },
      { sp:"Captain Hellinger", t:"They won't respond to my discovery requests." },
      { sp:"Alicia Florrick", t:"My client is suing the military contractor Martinel Security" },
      { sp:"Bucky Stabler", t:"Martinel Security is immune from all civil actions, including this subpoena." },
      { sp:"Bucky Stabler", t:"A serviceman or woman, such as the plaintiff, cannot sue the military." },
      { sp:"Alicia Florrick", t:"So they would be subject to court-martial?" },
      { sp:"Judge Kuhn", t:"I will grant the subpoena." },
      { sp:"Bucky Stabler", t:"Objection. Hearsay, Your Honor." },
      { sp:"Judge Kuhn", t:"Uh... overruled." },
      { sp:"Bucky Stabler", t:"Defense Exhibit D, Your Honor." },
      { sp:"Judge Kuhn", t:"As such, I'm afraid I must dismiss the case." }
    ],
    sceneNote:{ en:"The whole episode is a trap made of one good argument: everything counsel does to show that the contractor is subject to military command - general orders, court-martial exposure, deployment by the high command - is also what brings the attacker within the immunity line, because the same logic makes him a soldier on active duty at the moment of the tort. Note the tactical layer as well: telling a self-represented client she will lose the motion, because local judges vote on fear of reversal rather than on logic; and the classic move of obtaining an order conditioned on a factual finding the other side can then satisfy with a single exhibit. The hearsay exchange is worth reading against the rules: a declaration against interest normally requires an unavailable declarant, whereas a statement offered against a party is simply an opposing party's statement, excluded from hearsay altogether.", zh:"全剧是一个由「好论证」构成的陷阱：律师用来证明承包商受军事指挥的一切材料——一般命令、受军事审判的连带义务、由高级指挥部部署——同时也把袭击者送进了豁免线之内，因为同一逻辑反过来使他成为侵权行为发生那一刻的现役军人。战术层面同样值得注意：告知一位自行出庭的当事人她赢不了这个动议，因为当地法官投票服从的是「怕被改判」而不是逻辑；以及争取到一项以某项事实认定为条件的命令，对方随后用一份证据就能满足该条件。传闻那一段宜对照规则阅读：不利于己的陈述通常以陈述人无法到庭为条件，而用于对抗一方当事人的陈述应归入对方当事人的陈述，根本不属于传闻。" },
    terms:[ "court_martial", "pro_se", "motion_to_compel", "discovery_request", "feres_doctrine", "immunity", "subpoena", "hearsay", "admission_against_interest", "objection", "sworn_testimony", "co_counsel" ],
    uk:{ en:"England and Wales has no equivalent of Feres: a service member may sue the Ministry of Defence in negligence where a duty of care is made out, subject to the combat-immunity limitation recognised in Smith v Ministry of Defence. Contractors are ordinary defendants in tort, though the Crown may be vicariously liable where personnel are integrated into its operations. Subpoenas do not exist in this form - witness summonses are issued by the court on application - and both hearsay and credibility are now regulated by the Civil Evidence Act 1995 and the CPR rather than by a fixed code of exceptions.", zh:"英格兰与威尔士并无 Feres 的对应制度：只要能确立注意义务，现役军人得因过失起诉国防部，仅受 Smith v Ministry of Defence 所承认的「战斗豁免」限制；承包商在侵权法上就是普通被告，人员被整合进其行动时官方也可能承担替代责任。英国没有美式传票，传唤证人须经法院签发证人令；传闻与可信度则由《1995年民事证据法》与民事诉讼规则调整，而不是一套固定的例外清单。" }
  },
  {
    id:"S04E07", ep:7, title:"Anatomy of a Joke", zhTitle:"笑话的解剖",
    summary:{ en:"Will defends comedian Therese Dodd against a $2 million claim brought by the television network that carried her late-night breast-examination routine. The court narrows the whole case to one question - whether the exposure was premeditated - while the defence argues that liability was created by the broadcaster's own Standards and Practices, not by FCC rules. In the same week Burl Preston uses the litigation as cover to price Lockhart/Gardner itself, and a settlement built around lobbying the FCC ends by collapsing the network's damages to nothing.", zh:"辩护律师为一名喜剧演员在深夜节目中的乳房自检桥段辩护，应对播出方电视网提出的200万美元索赔。法院把全案收拢为一个问题——暴露行为是否出于预谋，辩方则主张真正造就责任的是电视网自定的播出标准，而非联邦通讯委员会的规则。同一周内，对方律师借该诉讼为跳板为律所本身估价；而围绕游说联邦通讯委员会达成的和解安排，最终使电视网的损害赔偿归于零。" },
    themes:[ {en:"Regulatory floor versus contractual ceiling: what the broadcasting rules permit does not release a performer from what the network promised.",zh:"监管底线与合同上限：法规允许播出，并不解除表演者对播出方承诺的义务。"}, {en:"Damages as the weakest link in a claim built to make a point rather than to recover a loss.",zh:"损害赔偿成为软肋：当诉讼意在立威而非填补损失时，损失要件最难成立。"}, {en:"Litigation used as an acquisition tool, and the limits of what a bankruptcy trustee may decide alone.",zh:"把诉讼当作收购的敲门砖，以及破产受托人能够单独决定的事项边界。"} ],
    scenes:[
      { sp:"Burl Preston", t:"You're being sued for $2 million, Ms. Dodd." },
      { sp:"Will Gardner", t:"Safe harbor. It's the time after 10:00 p.m. and before 6:00 a.m." },
      { sp:"Burl Preston", t:"Ms. Dodd signed a contract with the network, not with the FCC." },
      { sp:"Will Gardner", t:"Your Honor, this lawsuit is a sham." },
      { sp:"Will Gardner", t:"Mr. Preston and his client, the network, know they can't get $2 million from my client." },
      { sp:"Will Gardner", t:"Mr. Preston, our client can't pay a tenth of that." },
      { sp:"Will Gardner", t:"And how will that look for your network, bankrupting a comedian whose mother died of breast cancer?" },
      { sp:"Burl Preston", t:"It'll look like we take decency on our airwaves seriously." },
      { sp:"Burl Preston", t:"There is one thing your client can do to quash our suit." },
      { sp:"Clarke Hayden", t:"It's not up to the firm. It's up to the courts." },
      { sp:"Diane Lockhart", t:"Burl Preston is trying to buy this firm in order to control you." },
      { sp:"Burl Preston", t:"We made an effort to reach such a settlement, Your Honor, but the results depend on something yet to be decided." },
      { sp:"Burl Preston", t:"That was an argument in another venue." },
      { sp:"Will Gardner", t:"There are no actual damages here, and this suit should be dismissed." }
    ],
    sceneNote:{ en:"Two kinds of advocacy in one episode. In the hearing, the case is fought over regulatory text (the safe harbor window), whose burden the exposure falls on (network Standards and Practices versus the performer), and finally over intent. In the settlement track, everything turns on leverage rather than law: what the other side fears from its own regulator, and what a client will concede to make a claim disappear. Watch how each counsel keeps the client's insolvency off the record while using it as the real argument.", zh:"同一集内两种辩护形态并存。听证程序中，双方围绕监管文本（避风港时段）、风险由谁承担（电视网自定标准还是表演者本人），最终围绕主观意图交锋；和解轨道上，胜负取决于筹码而非法律——取决于对方害怕其监管机构作出什么决定，以及当事人愿意让步到何种程度才能让诉讼消失。注意观察律师如何在不把当事人资不抵债写入笔录的前提下，把它当作真正的论据来使用。" },
    terms:[ "safe_harbor", "premeditation", "liable", "settlement", "quash", "actual_damages", "venue", "Chapter_11", "equity_partner", "severance_package", "nonfinancial_side_agreement" ],
    uk:{ en:"The US 'safe harbor' for broadcast indecency has no direct English equivalent; the nearest analogue is Ofcom's watershed, after which material of an adult nature may be shown with protections attached. US networks also self-censor through Standards and Practices departments, which bind performers contractually well beyond what the broadcasting rules require - the usual source of the kind of dispute litigated here.", zh:"美国广播电视针对低俗内容的「避风港」时段在英国并无直接对应制度，最接近的是通信管理局规定的「分水岭」（watershed）时点，此后在附加保护措施的前提下可播出成人性质内容。美国电视网另设 Standards and Practices 部门自我审查，其对表演者的合同约束远宽于法定播出规则——这类纠纷通常正由此而生。" }
  },
  {
    id:"S04E08", ep:8, title:"Here Comes the Judge", zhTitle:"法官驾到",
    summary:{ en:"Judge Harrison Creary presides over the prosecution of Gwyneth Van Zanten with open contempt for Will, needling defence counsel from the bench about a past suspension and telling him over drinks at a bar that the client is guilty. Alicia answers first with a motion that he recuse himself and, when that is denied along with a finding of contempt, with a motion to substitute him for cause - which takes the case out of his hands and sends the single issue of his prejudice to another judge, heard as 'a trial within a trial'.", zh:"主审法官在谋杀案审理中公开敌视辩护律师，不仅当庭以对方曾被暂停执业为由讥刺，还在酒吧里直言被告有罪。律师先申请该法官自行回避；在申请被驳回并被当场认定藐视法庭后，转而提出有因更换法官动议，使案件脱离该法官之手，并将其是否存在偏见这一唯一争点交另一名法官以「案中案」的方式审理。" },
    themes:[ {en:"Recusal asked politely versus substitution demanded with prejudice alleged - the escalation ladder when a judge will not step aside.",zh:"请求自行回避与指称偏见要求更换：当法官拒绝退场时的升级路径。"}, {en:"Proving bias indirectly, through a law clerk, a meeting sponsor and the judge's own habits, rather than through his words.",zh:"以间接方式证明偏见：借助法官助理、互助会同伴与法官本人的生活习惯，而非仅凭其言辞。"}, {en:"The price of attacking a judge: contempt in the moment, and a harder bench waiting afterwards.",zh:"挑战法官的代价：当下的藐视法庭认定，以及此后更难应付的法官。"} ],
    scenes:[
      { sp:"Will Gardner", t:"My client has stated that she was faithful to her late husband and that they were happily married." },
      { sp:"Laura Hellinger", t:"Objection, Your Honor. Counsel is testifying." },
      { sp:"Will Gardner", t:"After you sent this text, my client immediately informed the police, didn't she?" },
      { sp:"Laura Hellinger", t:"Not only that, he's asking for hearsay." },
      { sp:"Will Gardner", t:"It goes to the defendant's state of mind." },
      { sp:"Will Gardner", t:"What were you offered in trade for your testimony here, Mr. Yates?" },
      { sp:"Judge Harrison Creary", t:"Are you having trouble getting out what you want, Mr. Gardner?" },
      { sp:"Alicia Florrick", t:"Your Honor, the defense requests an issues conference in chambers." },
      { sp:"Alicia Florrick", t:"Ahem. Your Honor, we move that you recuse yourself." },
      { sp:"Alicia Florrick", t:"You've given us no alternative, Your Honor, but to file a motion to substitute Your Honor for cause." },
      { sp:"Judge Harrison Creary", t:"No, it is not your right to disrupt my court. You're in contempt." },
      { sp:"Judge Peter Dunaway", t:"This hearing is, in effect, a trial within a trial." },
      { sp:"Judge Peter Dunaway", t:"Yes, counselor. Unfortunately, AA is not covered by client, patient or clergy privileges, and answers can be compelled here." },
      { sp:"Judge Peter Dunaway", t:"Therefore, I am granting the defense's motion to substitute." }
    ],
    sceneNote:{ en:"A compact manual on attacking the bench. Note the order of operations: an issues conference is requested on the record, a recusal motion is put to the judge himself, and only when that fails - and contempt lands - does counsel file to substitute, which divests him at once. Notice too how the defence structures its cross of the cooperating witness around what he was paid, and how the second hearing narrows everything to one issue, with the rules of evidence applying inside it.", zh:"一份关于「挑战法官」的简明操作手册。注意先后次序：先请求记入笔录的争点会议，再向该法官本人提出自行回避动议；只有在动议被驳回并被认定藐视法庭之后，才提出更换法官——后者一经提出即剥夺其控制权。同时留意辩方如何围绕污点证人的对价展开交叉询问，以及后一场听证如何适用证据规则，把全案收拢到唯一争点。" },
    terms:[ "counsel_is_testifying", "hearsay", "state_of_mind", "calls_for_narrative", "calls_for_speculation", "in_chambers", "recuse", "motion_to_substitute", "contempt", "privilege", "actus_reus", "plea_bargain" ],
    uk:{ en:"US practice keeps a judge's own recusal and a party's motion to substitute for cause distinct, and the latter is decided by a different judge on a confined record. England and Wales has no motion to substitute: bias is met by inviting the judge to recuse, and the test is whether a fair-minded and informed observer would conclude there was a real possibility of bias. Nor is there any privilege covering what is shared at an addiction support meeting; compellable testimony is compellable, sympathy aside.", zh:"美国法区分法官自行回避与当事人提出的附理由更换法官动议，后者由另一名法官在受限笔录上裁决。英格兰与威尔士没有更换法官的动议：偏见问题通过请求法官回避解决，审查标准是「公正且知情的观察者是否会认为存在偏见的现实可能性」。戒瘾互助会上的发言同样不受任何特权保护——可被强制的证言就是可被强制的，同情不改变这一点。" }
  },
  {
    id:"S04E09", ep:9, title:"A Defense of Marriage", zhTitle:"为婚姻辩护",
    summary:{ en:"Alicia and Will defend a CFO accused of a $430 million fraud tied to his employer, while a parallel will contest pits Veronica Loy against the deceased's son. The trial becomes a constitutional battle over the Defense of Marriage Act: the firm wants to ride the case to the Supreme Court, the government invokes spousal privilege to keep a wiretap of the husband and wife out, and a 'spousal shield' fight collides with witness impeachment. Along the way the lawyers trade objections on relevance, argumentativeness and scope, take a deposition, and weigh a plea bargain.", zh:"艾丽西亚与威尔代理一名因涉嫌职务上四亿三千万美元欺诈而受指控的财务总监，同时一起遗嘱争议让维罗妮卡·洛伊与死者的儿子对簿公堂。庭审演变为围绕《保卫婚姻法案》的宪法之战：律所想把案件送上联邦最高法院，政府援引婚姻特权将夫妻间的窃听录音挡在门外，而「配偶屏蔽」之争又与证人弹劾正面相撞。过程中律师们就相关性、好辩性与询问范围不断提出异议，进行证言录取，并权衡一份辩诉交易。" },
    themes:[ {en:"Spousal privilege and the 'spousal shield': when a spouse's communications are protected, and how the protection shifts when the spouse becomes a witness rather than a defendant.",zh:"婚姻特权与「配偶屏蔽」：配偶间沟通何时受保护，以及当配偶从被告转为证人时保护如何变化。"}, {en:"Constitutional litigation over the Defense of Marriage Act and the strategic pull between a precedent-setting win and a simple acquittal.",zh:"围绕《保卫婚姻法案》的宪法诉讼，以及「开创先例的胜利」与「单纯无罪开释」之间的策略拉扯。"}, {en:"Trial mechanics: objections (relevance, argumentative, beyond scope), impeachment, depositions and plea bargaining.",zh:"庭审技术：异议（相关性、好辩性、超范围）、弹劾、证言录取与辩诉交易。"} ],
    scenes:[
      { sp:"Judge", t:"I will review precedent on this." },
      { sp:"Arthur Shipton", t:"to not enforce the Defense of Marriage Act." },
      { sp:"AUSA Bucky Stabler", t:"Objection. Counselor is testifying." },
      { sp:"Judge", t:"Only he is allowed to object." },
      { sp:"Alicia Florrick", t:"Objection, Your Honor. Relevance?" },
      { sp:"Alicia Florrick", t:"Objection. Argumentative." },
      { sp:"Alicia Florrick", t:"Nothing further, Your Honor." },
      { sp:"Will Gardner", t:"You can't appeal a win." },
      { sp:"Alicia Florrick", t:"admitting that he committed fraud?" },
      { sp:"Alicia Florrick", t:"They opened the door" },
      { sp:"Alicia Florrick", t:"We need to subpoena what they have." },
      { sp:"Alicia Florrick", t:"Beyond the scope." },
      { sp:"Diane Lockhart", t:"That's a Class 3 felony." },
      { sp:"Alicia Florrick", t:"to get them to change their will." }
    ],
    sceneNote:{ en:"This episode is a clinic in evidentiary and constitutional skirmishing. Watch how the same conversation is first shielded by spousal privilege, then exposed for impeachment once the spouse is no longer a defendant, and how the lawyers use narrow objections (relevance, argumentative, beyond scope) to shape the record. The DOMA thread shows the firm exploiting a routine fraud trial as a vehicle for Supreme Court precedent.", zh:"本集是证据与宪法交锋的样板。注意同一段对话先受婚姻特权屏蔽，待配偶不再是被告后又因证人弹劾而被揭开；律师们用窄口径异议（相关性、好辩性、超范围）塑造庭审记录。DOMA 线索则显示律所把一桩寻常欺诈审判当作叩开最高法院先例的载体。" },
    terms:[ "spousal_privilege", "defense_of_marriage_act", "wiretap", "precedent", "subpoena", "impeachment", "plea_bargain", "felony", "deposition", "character_witness" ],
    uk:{ en:"In the US the marital communications privilege and the spousal testimonial privilege are distinct and vary by state; at the federal level a spouse may still be compelled in many circumstances. In England and Wales spouses were historically incompetent but are now competent and compellable witnesses, while the analogous protection is limited to communications made in circumstances of confidence. Same-sex marriage has been lawful in England and Wales since the Marriage (Same-Sex Couples) Act 2013.", zh:"在美国，婚姻沟通特权与配偶作证特权彼此独立且各州不同；联邦层面配偶在许多情形下仍可被强制作证。英格兰与威尔士历史上配偶无作证资格，如今已具作证能力与可强制性，类似的保密沟通保护则限于在特定保密情形下作出的沟通。英格兰与威尔士自《2013年同性婚姻法》起承认同性婚姻。" }
  },
  {
    id:"S04E10", ep:10, title:"Battle of the Proxies", zhTitle:"代理权之战",
    summary:{ en:"Will defends Gary Kuharski, accused of a Minooka murder, while a Chicago parallel case and an exchange of prosecutors across county lines taint the evidence. The trial is a masterclass in evidentiary warfare: objections for hearsay, relevance, speculation and leading questions; a res gestae exception; a 'Fruit of the Poisonous Tree' attack on evidence obtained without a warrant; fights over the exhibit list; and a privilege point when attorney-client privilege is said to be voided. The jury returns a guilty verdict even as the defence suspects an innocent man was convicted.", zh:"威尔代理被控在米努卡杀人的加里·库哈尔斯基，而芝加哥的平行案件与跨郡的检察官互换玷污了证据。庭审堪称证据战教科书：针对传闻、相关性、猜测与诱导性提问的异议；res gestae（附随事件）例外；对无证取得证据发动「毒树之果」攻击；围绕证据清单的争夺；以及当律师—委托人特权被指失效时的特权交锋。尽管辩方怀疑判错了人，陪审团仍作出有罪裁决。" },
    themes:[ {en:"Cross-jurisdictional evidence and the exclusionary rule: evidence barred in one court (warrantless search) and its 'Fruit of the Poisonous Tree' spillover into another.",zh:"跨法域证据与排除规则：在一地因无证搜查被排除的证据，其「毒树之果」如何溢出到另一地。"}, {en:"Evidentiary objections drilled in context: hearsay, relevance, speculation, leading, res gestae, and the exhibit list.",zh:"在语境中演练证据异议：传闻、相关性、猜测、诱导、附随事件例外与证据清单。"}, {en:"Professional responsibility: the duty to zealously represent a client even when the lawyer doubts the client's innocence.",zh:"职业责任：即使律师怀疑客户有罪，仍须勤勉代理客户。"} ],
    scenes:[
      { sp:"Judge", t:"You will find yourself in a jail cell." },
      { sp:"Judge", t:"Sorry, Lee, I will overrule." },
      { sp:"Alicia Florrick", t:"Objection, hearsay." },
      { sp:"Alicia Florrick", t:"Res gestae exception, Your Honor." },
      { sp:"Judge", t:"Overruled. You may answer." },
      { sp:"Alicia Florrick", t:"Speculation." },
      { sp:"Judge", t:"Sustained." },
      { sp:"Alicia Florrick", t:"Objection, leading." },
      { sp:"Alicia Florrick", t:"Objection, Your Honor, relevance." },
      { sp:"Judge", t:"We will allow this evidence." },
      { sp:"Judge", t:"No, Alma, I will allow." },
      { sp:"Jury Foreman", t:"...guilty." },
      { sp:"Will Gardner", t:"zealously represent our clients." },
      { sp:"Will Gardner", t:"convict an innocent man." }
    ],
    sceneNote:{ en:"The episode shows two courts applying the same Fourth Amendment exclusion, and the defence trying to import Chicago's warrantless-search bar into Minooka. Watch the tight sequencing of objection, ruling and exception (res gestae, then overruled), and notice how the exhibit-list objection is really a discovery-dispute workaround. The final verdict lands even though the constitutional exclusion means the strongest evidence never got a stringent look.", zh:"本集展现两个法院适用同一第四修正案排除规则，辩方试图把芝加哥的无证搜查禁令引入米努卡。注意异议、裁定与例外（res gestae，随后被推翻）之间紧凑的衔接，以及证据清单异议实质是证据开示争议的变通。最终裁决落下，尽管宪法排除导致最强证据从未受到严格审查。" },
    terms:[ "contempt", "fruit_of_poisonous_tree", "warrant", "attorney_client_privilege", "exhibit", "res_gestae", "speculation", "leading_question", "verdict", "due_process" ],
    uk:{ en:"The US has a strict exclusionary rule with the 'fruit of the poisonous tree' doctrine: evidence derived from an unconstitutional search is itself excluded. England and Wales have no automatic rule; under PACE 1984 the court has a discretion to exclude unfair evidence (s.78) and confessions obtained by oppression or unreliably (s.76), and unlawfully obtained real evidence is generally still admissible if relevant.", zh:"美国采严格的证据排除规则并辅以「毒树之果」理论：由违宪搜查衍生的证据本身亦被排除。英格兰与威尔士无自动排除规则；依《1984年警察与刑事证据法》，法院有权裁量排除不公平证据（第78条）或以压迫或不可靠方式取得的供述（第76条），而非法取得的实物证据若具相关性通常仍可采。" }
  },
  {
    id:"S04E11", ep:11, title:"Boom De Yah Da", zhTitle:"轰隆隆",
    summary:{ en:"Two disputes run together: a personal-injury suit over a koi pond (mosquitoes, West Nile virus, attractive nuisance, trespass and proximate cause) and the firm's bankruptcy, where the court-appointed trustee Clarke Hayden forces a mediation over a threatened merger. The episode is thick with civil procedure: a court-mandated deposition that the deponent keeps dodging, objections (hearsay, foundation, relevance), preservation of objection for the record, a contempt threat, and a $13 million settlement in play.", zh:"两起纠纷交织：一桩关于锦鲤池的人身伤害诉讼（蚊子、西尼罗河病毒、诱引妨害、非法侵入与近因），以及律所的破产——法院指定的受托人 Clarke Hayden 就一桩受到威胁的合并强行启动调解。本集民诉色彩浓厚：被取证人不断躲避的法院强制证言录取、各类异议（传闻、基础、相关性）、异议记入记录的保留、藐视法庭的威胁，以及一笔一千三百万美元的和解。" },
    themes:[ {en:"Civil procedure in motion: court-mandated depositions, objections and their preservation, and contempt as the sanction that finally produces the witness.",zh:"运行中的民事诉讼程序：法院强制证言录取、异议及其保留，以及最终逼出证人的藐视法庭制裁。"}, {en:"Tort building blocks: attractive nuisance, trespass and proximate cause in a premises-liability claim.",zh:"侵权构成要素：诱引妨害、非法侵入与近因在占有者责任之诉中的运用。"}, {en:"Bankruptcy mediation: the trustee's leverage over a firm's restructuring and the creditors' bargain.",zh:"破产调解：受托人对事务所重整的杠杆，以及债权人之间的交易。"} ],
    scenes:[
      { sp:"Judge", t:"settle any and all objections." },
      { sp:"Alicia Florrick", t:"She will make you address my question." },
      { sp:"Alicia Florrick", t:"Objection. That's hearsay." },
      { sp:"Judge", t:"Your objection has been noted." },
      { sp:"Alicia Florrick", t:"in contempt in absentia?" },
      { sp:"Judge", t:"I rule for the plaintiff." },
      { sp:"Judge", t:"at 10:00 a.m. or be held in contempt." },
      { sp:"Kalinda Sharma", t:"acquire the warrant." },
      { sp:"Judge", t:"That's my ruling." },
      { sp:"Will Gardner", t:"liable for that trespass." },
      { sp:"Will Gardner", t:"and your client is not a child." },
      { sp:"Alicia Florrick", t:"Which means court." },
      { sp:"Louis Canning", t:"This is a conflict of interest." },
      { sp:"Clarke Hayden", t:"Either way, I'll see you in mediation." }
    ],
    sceneNote:{ en:"The episode pairs a small tort with a large insolvency, and shows how the same tools (deposition, objection, contempt, settlement) operate in both. Note the 'judge on call' device to settle objections instantly, the explicit preservation of objection 'for the record', and how the threat of contempt in absentia finally compels the witness the firm had chased for fourteen months.", zh:"本集将一桩小侵权与一宗大破产并置，展现同样的工具（证言录取、异议、藐视、和解）在两处如何运作。注意「随传随到法官」即时裁定异议的安排、异议「记入记录」的明确保留，以及缺席藐视威胁最终逼出事务所追了十四个月的证人。" },
    terms:[ "deposition", "mediation", "foundation", "trespass", "conflict_of_interest", "attractive_nuisance", "proximate_cause", "stipulation", "warrant", "contempt" ],
    uk:{ en:"US discovery relies heavily on oral depositions taken under oath before trial; England and Wales largely does without them, using written questions (interrogatories), witness statements and affidavits instead. Mediation is encouraged in both systems, but in England the Civil Procedure Rules let a court stay proceedings to mediate and impose cost sanctions on a party that refuses unreasonably, whereas US mediation is usually contractual or court-referred without automatic cost penalties.", zh:"美国证据开示高度依赖审前宣誓口头证言录取；英格兰与威尔士基本不用，而以书面质询、证人陈述与宣誓书替代。两地都鼓励调解，但在英格兰《民事诉讼规则》可让法院中止程序以进行调解，并对无理拒绝者处以费用制裁，而美国调解通常为约定或法院转介，无自动费用惩罚。" }
  },
  {
    id:"S04E12", ep:12, title:"Je Ne Sais What", zhTitle:"不知所云",
    summary:{ en:"A weekend of legal triage: Will covers a contract-enforcement arbitration for a $5 million endorsement deal while Diane and Elsbeth fight a Court of Arbitration for Sport (CAS) doping proceeding in French and English, and Alicia scrambles to get a client to a weekend bond hearing. The CAS saga turns on chain of custody, a reversed burden of proof, confidentiality of a prior arbitration, and a three-judge panel that decides by majority; the ruling stands and the client can appeal to the Supreme Court.", zh:"一个周末的法律急救：威尔代班一场涉及五百万美元代言合约强制执行的仲裁，而黛安与埃尔斯贝丝在一场以英法双语进行的体育仲裁院（CAS）兴奋剂程序中奋战，艾丽西亚则忙着把客户送到周末的保释听证。CAS 风波围绕证据保管链、倒置的举证责任、先前仲裁的保密性，以及以多数决作出裁决的三人合议庭展开；裁决维持，客户可上诉至最高法院。" },
    themes:[ {en:"Arbitration practice: a contract-enforcement arbitration and a CAS sports tribunal, each with its own rules, language and panel, and limited grounds to appeal.",zh:"仲裁实务：合约强制执行仲裁与 CAS 体育仲裁庭，各有规则、语言与合议庭，且上诉事由受限。"}, {en:"Evidentiary and procedural pivots: chain of custody of a doping sample, a reversed burden of proof, and a majority 'ruling stands'.",zh:"证据与程序转折：兴奋剂样本的证据保管链、倒置的举证责任，以及「裁决维持」的多数决。"}, {en:"The weekend bond hearing and the constitutional hook used to force a judge to transport a detained client.",zh:"周末保释听证，以及借宪法事由迫使法官移送在押客户的手法。"} ],
    scenes:[
      { sp:"Will Gardner", t:"her contract is voided." },
      { sp:"Diane Lockhart", t:"like any other appeals hearing." },
      { sp:"Arbitrator", t:"There is no charge." },
      { sp:"Will Gardner", t:"Objection." },
      { sp:"Arbitrator", t:"This is not Law & Order." },
      { sp:"Diane Lockhart", t:"chain of custody." },
      { sp:"Elsbeth Tascioni", t:"to prove you're innocent." },
      { sp:"Alicia Florrick", t:"This is a constitutional matter." },
      { sp:"Will Gardner", t:"But I have one more witness:" },
      { sp:"Elsbeth Tascioni", t:"Judge Villapique." },
      { sp:"Will Gardner", t:"We're here to win." },
      { sp:"Judge Villapique", t:"This is not an American court, Mr. Gardner." },
      { sp:"Diane Lockhart", t:"The Italian judge is for us." },
      { sp:"Arbitrator", t:"The ruling stands." }
    ],
    sceneNote:{ en:"The episode is a study in forum-shopping and procedural mismatch: an American firm dropped into a Swiss sports tribunal where the burden of proof is reversed and the panel votes by majority. Watch how chain of custody becomes the whole ballgame, how 'confidential' prior arbitration is used as a sword, and how the weekend bond hearing is forced through a constitutional framing that compels the presiding judge to move the detainee.", zh:"本集是研究择地行诉与程序错配的范本：一家美国律所被抛入瑞士体育仲裁庭，那里举证责任倒置、合议庭以多数决投票。注意证据保管链如何成为全局关键，先前的「保密」仲裁如何被用作攻防武器，以及周末保释听证如何借宪法框架迫使主审法官移送在押者。" },
    terms:[ "arbitration", "contract", "void", "chain_of_custody", "burden_of_proof", "appeal", "three_judge_panel", "bail", "confidential", "constitutional" ],
    uk:{ en:"In both the US and England arbitration is a consensual, private dispute process with very limited court review (US Federal Arbitration Act; UK Arbitration Act 1996), and sports doping is handled through the Court of Arbitration for Sport in Lausanne under the WADA Code, whose awards are enforced internationally via the New York Convention. The UK has no 'bond hearing' as such; pre-trial release is decided by a magistrates' court bail application, and strict-liability anti-doping means the athlete need not intend the violation.", zh:"在美国与英格兰，仲裁均为合意性、私密的解纷程序，法院审查极度有限（美国《联邦仲裁法》；英国《1996年仲裁法》）；体育兴奋剂由位于洛桑的体育仲裁院依《世界反兴奋剂条例》处理，其裁决通过《纽约公约》在国际上执行。英国并无「保释听证」一说；审前释放由治安法院保释申请决定，而反兴奋剂采严格责任，运动员无需有违规故意。" }
  },
  {
    id:"S04E13", ep:13, title:"The Seven Day Rule", zhTitle:"七天规则",
    summary:{ en:"Two interlocking fights: the firm's bid for a five-month extension in bankruptcy court, opposed by its own creditor Louis Canning, and a prenuptial-agreement subplot for Neil Gross. Alicia is named an equity partner mid-crisis. The hearing turns on objections (relevance, asked and answered, attorney is testifying), a trustee's oversight, and whether a creditor's motive is admissible.", zh:"两条交织的战线：本所在破产法院争取五个月延期，却遭到自身债权人路易斯·坎宁的反对；以及尼尔·格罗斯的婚前协议支线。危机之中艾丽西亚被擢升为权益合伙人。听审围绕多项异议（相关性、已问已答、律师代作证）、破产受托人的监管，以及债权人动机可否采纳而展开。" },
    themes:[ {en:"Bankruptcy-court extension practice: showing progress to a trustee, a creditor opposing, and the firm's survival math.",zh:"破产法院延期实务：向受托人展示进展、债权人反对，以及事务所的生存算计。"}, {en:"Prenup drafting as a worst-case contract and the leverage of a $600,000 equity-partner buy-in.",zh:"婚前协议作为最坏情形合同，以及六十万美元权益合伙人出资所代表的杠杆。"}, {en:"Objection craft in a hearing: relevance, asked-and-answered, and attorney-is-testifying as repeated swords.",zh:"听审中的异议技巧：相关性、已问已答、律师代作证作为反复出鞘的剑。"} ],
    scenes:[
      { sp:"Paul", t:"It's a prenup." },
      { sp:"Diane Lockhart", t:"We want you to join us as an equity partner." },
      { sp:"Alicia Florrick", t:"My buy-in to the firm is $600,000." },
      { sp:"Rochelle", t:"The prenup is voided." },
      { sp:"David Lee", t:"but this contract is about worst-case scenarios." },
      { sp:"Diane Lockhart", t:"We have cut our debt in half, Your Honor." },
      { sp:"Alicia Florrick", t:"If we wanna argue for an extension, we need to show the court some progress." },
      { sp:"Louis Canning", t:"I renew my objection to this witness, Your Honor." },
      { sp:"Will Gardner", t:"Objection. Asked and answered." },
      { sp:"Louis Canning", t:"Objection. Attorney is testifying." },
      { sp:"Judge", t:"Enough, all of you!" },
      { sp:"Will Gardner", t:"A five-month extension." },
      { sp:"Alicia Florrick", t:"I've been subpoenaed in court." },
      { sp:"Diane Lockhart", t:"We have a trustee who thinks of us as a decimal point." }
    ],
    sceneNote:{ en:"A study in forum survival: a firm one week from liquidation argues progress to a bankruptcy trustee while its largest creditor tries to block the extension by attacking witness motives. Watch how the same objection formulas (relevance, asked and answered, attorney is testifying) get recycled, and how Alicia's $600,000 equity-partner buy-in reframes her from associate to owner exactly when the firm needs her capital.", zh:"一出绝境求生的范本：距清算仅剩一周的事务所向破产受托人论证进展，而其最大债权人却借攻击证人动机试图阻断延期。注意同一套异议套话（相关性、已问已答、律师代作证）如何被反复使用，以及艾丽西亚六十万美元的权益合伙人出资如何在事务所最需要资本时把她从聘用律师重塑为所有者。" },
    terms:[ "prenuptial_agreement", "void", "equity_partner", "objection", "relevance", "bankruptcy", "creditor", "settlement", "subpoena", "trustee", "extension" ],
    uk:{ en:"In England corporate insolvency runs through administration or liquidation overseen by an insolvency practitioner rather than a US-style 'bankruptcy court' trustee. Prenuptial agreements became weighty after Radmacher v Granatino [2010], though not automatically binding. An 'equity partner' maps to a member of a solicitors' LLP; a 'subpoena' is a witness summons; and a creditor opposing an extension would do so in the insolvency proceedings, not a state court.", zh:"在英格兰，公司破产通过由破产执业人监管的「管理」或「清算」程序进行，而非美国式的「破产法院」受托人。婚前协议在 Radmacher v Granatino [2010] 案后获得重要分量，但并非自动具有约束力。「权益合伙人」对应律师事务所 LLP 的成员；「传票」为证人传票；债权人反对延期须于破产程序中提出，而非州法院。" }
  },
  {
    id:"S04E14", ep:14, title:"Red Team Blue Team", zhTitle:"红队蓝队",
    summary:{ en:"A mock trial of the energy drink Thief becomes a proxy war between firms. The plaintiffs' side lays out a wiretap theory, a hostile witness and a witness-list fight, while the defense leans on objections, a gag order from an unrelated matter, and the threat of contempt. The episode is a satirical tour of trial mechanics run as a game.", zh:"一场针对能量饮料 Thief 的模拟审判，成了律所之间的代理人战争。原告方铺陈窃听理论、敌意证人与证人名单之争，被告方则倚重异议、一桩无关案件的禁言令，以及藐视法庭的威胁。本集以游戏之姿戏拟了庭审机制的全貌。" },
    themes:[ {en:"Mock-trial as training and as shadow litigation: how a simulated jury rehearses real evidentiary fights.",zh:"模拟审判既是训练也是影子诉讼：模拟陪审团如何预演真实的证据交锋。"}, {en:"Wiretap law and the threshold ('dirty calls') needed to authorize surveillance.",zh:"窃听法与授权监控所需的门槛（「肮脏通话」）。"}, {en:"The gag order and contempt as cross-matter weapons that bleed into the mock proceeding.",zh:"禁言令与藐视法庭作为跨案件的武器，渗入模拟程序。"} ],
    scenes:[
      { sp:"David Lee", t:"This is a wiretap." },
      { sp:"Alicia Florrick", t:"requires three dirty calls to warrant a wiretap." },
      { sp:"Alicia Florrick", t:"So they didn't have enough calls to warrant the wiretap." },
      { sp:"Will Gardner", t:"We're calling him as a hostile witness." },
      { sp:"Will Gardner", t:"This name was not on the plaintiff's witness list." },
      { sp:"Will Gardner", t:"Objection. Relevance?" },
      { sp:"Will Gardner", t:"Objection. Counselor is testifying." },
      { sp:"Judge", t:"you're going to find yourselves in contempt." },
      { sp:"Alicia Florrick", t:"it was subject to a gag order." },
      { sp:"Judge", t:"Any gag order's not the concern of this court." },
      { sp:"Thief Attorney", t:"We'll see you in court." },
      { sp:"Eli Gold", t:"I will wear a wire." },
      { sp:"Will Gardner", t:"If you still want to be an equity partner, we want you." },
      { sp:"Alicia Florrick", t:"I'm sorry, Will." }
    ],
    sceneNote:{ en:"The mock trial mirrors a real one: a wiretap authorized on a flawed 'three dirty calls' showing, a witness sprung as hostile, and a witness list used as a trap. The gag order from a settled wrongful-death matter becomes a cudgel in the game, and contempt is threatened as easily as it is in a real courtroom. Watch how the lawyers rehearse the very objections they will later raise for real.", zh:"模拟审判映射着真实审判：基于有缺陷的「三通肮脏通话」授权窃听、把证人当作敌意证人抛出、以证人名单设套。一桩已和解的过失致死案的禁言令成了游戏中的棍棒，藐视法庭的威胁信手拈来。注意律师们如何预演他们日后将在真实庭审中提出的那些异议。" },
    terms:[ "wiretap", "felony", "hostile_witness", "witness_list", "relevance", "contempt", "gag_order", "settlement", "equity_partner" ],
    uk:{ en:"In England interception of communications is governed by the Regulation of Investigatory Powers Act 2000 and the Investigatory Powers Act 2016, needing a warrant from the Secretary of State, not a judge's 'dirty calls' tally. 'Contempt of court' is a coherent offence under the Contempt of Court Act 1981; a 'gag order' is an injunction restraining publication; and a hostile (adverse) witness can be cross-examined as such under the Civil Evidence Act 1995.", zh:"在英格兰，通信拦截由《2000年侦查权规制法》及《2016年侦查权法》规范，须由国务大臣签发令状，而非法官的「肮脏通话」计数。「藐视法庭」是《1981年藐视法庭法》下的完整罪名；「禁言令」为限制发表的禁令；敌意（对抗性）证人可依《1995年民事证据法》作为此类证人交叉询问。" }
  },
  {
    id:"S04E15", ep:15, title:"Going for the Gold", zhTitle:"为戈尔德而战",
    summary:{ en:"Alicia and the firm are pulled into a 'sham' defamation suit brought less to win than to fish for testimony usable in Eli Gold's federal prosecution. The matter turns on standing, a dismissal with prejudice, attorney-client privilege, a subpoena, and a court-appointed trustee overseeing the firm's bankruptcy.", zh:"艾丽西亚与事务所被卷入一桩「虚假」诽谤之诉——其目的不在胜诉，而在套取可用于埃利·戈尔德联邦刑事追诉的证词。本案围绕诉讼资格、有既判力的驳回、律师—客户特权、传票，以及监管事务所破产的法院指定受托人而展开。" },
    themes:[ {en:"The sham lawsuit as a discovery device: using a civil case to surface testimony for a parallel criminal prosecution.",zh:"以虚假之诉作为取证手段：借民事案件逼出可用于平行刑事追诉的证词。"}, {en:"Civil-vs-criminal forum split and the 'dismissal with prejudice' exit the defense wants.",zh:"民事与刑事法院的分割，以及辩方想要的「有既判力的驳回」出口。"}, {en:"Attorney-client privilege and standing as shields against a fishing expedition.",zh:"律师—客户特权与诉讼资格作为抵御滥诉渔利的盾牌。"} ],
    scenes:[
      { sp:"AUSA Perrotti", t:"Then take me to court." },
      { sp:"Eli Gold", t:"the State's Attorney's office is looking for a new outside firm to represent it on its civil suits." },
      { sp:"Alicia Florrick", t:"this is in civil court." },
      { sp:"AUSA Perrotti", t:"We take the defamation of our client very seriously." },
      { sp:"AUSA Perrotti", t:"we move for a dismissal with prejudice." },
      { sp:"Judge", t:"You have no standing in this court," },
      { sp:"Alicia Florrick", t:"you may be subject to subpoena in federal court." },
      { sp:"Alicia Florrick", t:"No, I enjoy attorney-client privilege." },
      { sp:"Alicia Florrick", t:"Objection. Relevance." },
      { sp:"Alicia Florrick", t:"Objection. Asked and answered." },
      { sp:"AUSA Perrotti", t:"Your Honor, you previously approved our extension for the production of our discovery." },
      { sp:"Judge", t:"or be held in contempt." },
      { sp:"Diane Lockhart", t:"We were under the control of a court-appointed trustee, Mr. Clarke Hayden." },
      { sp:"Judge", t:"The charge still stands." }
    ],
    sceneNote:{ en:"The genius of the setup is forum: a defamation claim in civil court exists mainly to put a witness on the stand where her answers can later be used in federal court. The defense answers with standing, privilege and a motion to dismiss with prejudice, while the firm's own bankruptcy trustee (Clarke Hayden) becomes a reason the charge 'still stands'. Watch how 'no standing' and 'attorney-client privilege' defuse the fishing expedition.", zh:"本集布局的妙处在「法院」：民事诽谤之诉的存在主要为了让证人在庭上作答，其回答日后可用于联邦法院。辩方以诉讼资格、特权与有既判力的驳回动议应对，而事务所自身的破产受托人（克拉克·海登）成了指控「仍然成立」的理由。注意「无诉讼资格」与「律师—客户特权」如何化解这场渔利式滥诉。" },
    terms:[ "defamation", "dismissal_with_prejudice", "standing", "subpoena", "attorney_client_privilege", "relevance", "co_conspirator", "contempt", "trustee" ],
    uk:{ en:"English defamation was reshaped by the Defamation Act 2013, which requires 'serious harm' and a defence of truth, honest opinion and public interest; a 'dismissal with prejudice' has no exact label but maps to strike-out or summary judgment on the merits. A 'subpoena' is a witness summons, 'attorney-client privilege' is legal professional privilege, and 'standing' is the claimant's sufficient interest to bring the claim.", zh:"英格兰诽谤法经《2013年诽谤法》重塑，要求「严重损害」并提供真实、诚实意见与公共利益的抗辩；「有既判力的驳回」无完全对应标签，近似依实体作出的撤销或即决判决。「传票」为证人传票，「律师—客户特权」为法律职业特权，「诉讼资格」为原告提起诉讼的足够利益。" }
  },
  {
    id:"S04E16", ep:16, title:"Runnin' with the Devil", zhTitle:"与恶魔同行",
    summary:{ en:"Lemond Bishop is accused of killing a confidential informant; the firm defends him at a preliminary hearing where the fight is over probable cause, a recanting witness, and prosecutorial coercion. The defense argues the government threatened a witness with lies, forcing the judge toward a motion to dismiss.", zh:"莱蒙德·毕晓普被控杀害一名 confidential informant（机密线人）；事务所在预审听证中为其辩护，争点是相当理由、翻供的证人，以及检方的胁迫。辩方主张政府以谎言威胁证人，将法官推向驳回动议。" },
    themes:[ {en:"The preliminary hearing as a probable-cause gate, not a trial, and the 'two cracks at bat' the defense fears.",zh:"预审听证作为相当理由关口而非审判，以及辩方所惧的「两次进攻机会」。"}, {en:"Witness recantation and prosecutorial coercion as grounds to exclude testimony and dismiss.",zh:"证人翻供与检方胁迫作为排除证词、驳回起诉的理由。"}, {en:"Bail, remand and the custody posture of a high-stakes defendant.",zh:"保释、羁押以及重大被告的拘禁态势。"} ],
    scenes:[
      { sp:"AUSA", t:"You're accused of killing a confidential informant at one of your health clubs." },
      { sp:"Judge", t:"Mr. Bishop will be remanded into the custody of a U.S. marshal." },
      { sp:"AUSA", t:"This is merely a preliminary hearing." },
      { sp:"Will Gardner", t:"If there isn't enough evidence, Mr. Bishop should be free." },
      { sp:"Will Gardner", t:"Objection, Your Honor." },
      { sp:"Will Gardner", t:"Absent that, we ask for bail." },
      { sp:"Kalinda Sharma", t:"Witness recanted." },
      { sp:"Alicia Florrick", t:"Your Honor, this is coercion, pure and simple." },
      { sp:"Judge", t:"Threatening a witness with lies in order to get him to testify leaves me with no other choice but to exclude said testimony." },
      { sp:"Judge", t:"I am going to be forced to dismiss." },
      { sp:"AUSA", t:"to amend the witness list to include Judy Bishop," },
      { sp:"Will Gardner", t:"Objection. How is this relevant?" },
      { sp:"Will Gardner", t:"This quid pro quo makes this witness unreliable." },
      { sp:"Will Gardner", t:"given the last minute addition to the witness list, we ask for a recess" }
    ],
    sceneNote:{ en:"The episode is a clinic on the preliminary hearing: a probable-cause gate where the defense tries to win early by exposing a coerced witness. The AUSA's threat of lies to secure testimony becomes the grounds to exclude it, and the judge edges toward dismissal. Watch the tactical dance around bail, the last-minute amended witness list, and the quid-pro-quo attack on a witness's motive.", zh:"本集是预审听证的实训：一道相当理由关口，辩方试图通过揭穿被胁迫的证人而早早取胜。检方以谎言相胁以取得证词，恰恰成为排除该证词、令法官倾向驳回的根据。注意围绕保释、临时修改的证人名单，以及以「对价交换」攻击证人动机的战术舞步。" },
    terms:[ "confidential_informant", "preliminary_hearing", "probable_cause", "remand", "bail", "coercion", "quid_pro_quo", "motion_to_dismiss", "relevance", "recant" ],
    uk:{ en:"England has no 'preliminary hearing' exactly; early case management and a plea and trial preparation hearing (PTPH) serve some functions, while a magistrates' court handles first appearance and mode of trial. 'Probable cause' has no direct UK equivalent; police need reasonable grounds to arrest, and bail is granted by magistrates. Threatening a witness is an offence under the Criminal Justice and Public Order Act 1994, and witness intimidation can void a conviction.", zh:"英格兰并无完全对应的「预审听证」；早期的案件管理与答辩及审判准备听证（PTPH）承担部分职能，治安法院处理首次到庭与审理方式。「相当理由」在英国无直接对应；警方须有合理理由方可逮捕，保释由治安法官决定。威胁证人属《1994年刑事司法与公共秩序法》下的罪行，证人受胁可推翻定罪。" }
  },
  {
    id:"S04E17", ep:17, title:"Invitation to an Inquest", zhTitle:"验尸调查之邀",
    summary:{ en:"The firm represents the estate in a coroner's inquest into the death of Illinois Supreme Court Justice Roger Ludwig, suspected of driving off the road. The proceeding mixes a jury, a Fifth Amendment invocation by Mrs. Ludwig, an EDR data fight, a motion to exclude, and a last-minute settlement before a jury could rule.", zh:"事务所代表遗产方，参与对伊利诺伊州最高法院法官罗杰·路德维希死因的验尸调查——疑似驾车坠路身亡。该程序杂糅了陪审团、路德维希夫人援引第五修正案、EDR 数据之争、排除动议，以及陪审团裁决前最后一刻的和解。" },
    themes:[ {en:"The coroner's inquest as a non-criminal fact-finding proceeding with its own jury and relaxed rules.",zh:"验尸调查作为非刑事的事实调查程序，拥有自己的陪审团与较为宽松的规则。"}, {en:"The Fifth Amendment right against self-incrimination invoked by a witness spouse, and its limits.",zh:"证人配偶援引的第五修正案不自证其罪权及其边界。"}, {en:"EDR ('black box') evidence and the motion to exclude as the fulcrum of the case.",zh:"EDR（「黑匣子」）证据与排除动议作为本案的支点。"} ],
    scenes:[
      { sp:"Wilk Hobson", t:"the coroner's inquest will find in our favor," },
      { sp:"Clerk", t:"Six jurors have been seated from the regular jury pool." },
      { sp:"Wilk Hobson", t:"Objection. Mr. Gardner is combining several questions..." },
      { sp:"Judge", t:"Whether it is or is not outrageous, I will decide." },
      { sp:"Judge", t:"Please have your evidence ready tomorrow, and I will review." },
      { sp:"Alicia Florrick", t:"my client to invoke her Fifth Amendment right not to testify." },
      { sp:"Mrs. Ludwig", t:"On counsel's advice, I am invoking my Fifth Amendment right not to answer." },
      { sp:"Will Gardner", t:"I'm gonna let the jury hear it." },
      { sp:"Diane Lockhart", t:"Wilk Hobson couldn't risk it going to a jury." },
      { sp:"Will Gardner", t:"I never expected them to settle." },
      { sp:"Will Gardner", t:"Objection. Goes beyond the scope." },
      { sp:"Will Gardner", t:"Evidence regarding the judge's last weeks," },
      { sp:"Will Gardner", t:"insufficient evidence." },
      { sp:"Will Gardner", t:"Fairness demands that a jury not only hear evidence as to suicide..." }
    ],
    sceneNote:{ en:"An inquest is not a trial: it seeks a conclusion about how someone died, not guilt. That looseness lets the firm float a suicide theory and lean on EDR data, while Mrs. Ludwig hides behind the Fifth Amendment. The judge's 'I will decide' signals the inquisitorial tilt. The matter ends not with a verdict but a settlement once the defense secures the evidence it wanted — a reminder that inquests are often preludes to civil or criminal fallout.", zh:"验尸调查不是审判：它探求死因结论，而非定罪。这种宽松让事务所抛出自杀理论、倚仗 EDR 数据，而路德维希夫人躲入第五修正案之后。法官的「由我决定」显露出其纠问式倾向。案件未以裁决收场，而在辩方取得想要的证据后和解——提醒人们：验尸调查常是民事或刑事余波的序曲。" },
    terms:[ "inquest", "fifth_amendment", "motion_to_exclude", "evidence", "jury", "settlement", "relevance", "suicide", "charges" ],
    uk:{ en:"In England a coroner's inquest is governed by the Coroners and Justice Act 2009, with a coroner (and often a jury for certain deaths) returning conclusions such as 'accident' or a narrative record; the old 'suicide' verdict was abolished in 2013. There is no US-style Fifth Amendment; the right to silence comes from the Police and Criminal Evidence Act 1984 and the privilege against self-incrimination, but a coroner can draw limited inferences.", zh:"在英格兰，验尸调查由《2009年验尸官与司法法》规范，由验尸官（特定死亡常配陪审团）作出「意外」或叙述式结论；旧的「自杀」结论于2013年废止。英国无美国式的第五修正案；沉默权源自《1984年警察与刑事证据法》及不自证其罪特权，但验尸官可作出有限推论。" }
  },
  {
    id:"S04E18", ep:18, title:"Death of a Client", zhTitle:"客户之死",
    summary:{ en:"The firm's client Ashbaugh is murdered, prompting a meditation on attorney-client privilege after death, while Peter dangles a vacant Illinois Supreme Court seat to Diane and uses Cary's conflicted loyalties. The episode weighs when privileged information survives, when it may be waived, and the line between advocacy and intimidation.", zh:"事务所的客户阿什博被谋杀，引出对「律师—客户特权于死后存续」的沉思；与此同时，彼得以空缺的伊利诺伊州最高法院席位为饵牵动黛安，并利用凯里矛盾的忠诚。本集权衡特权信息何时存续、何时可被放弃，以及代理与胁迫之间的界线。" },
    themes:[ {en:"Attorney-client privilege and its survival (and limited exceptions) after the client's death.",zh:"律师—客户特权及其在客户死后的存续（及有限例外）。"}, {en:"The Supreme Court seat as political currency and the lobbying/conflict questions it raises.",zh:"最高法院席位作为政治筹码，及其引发的游说与利益冲突问题。"}, {en:"Confidentiality vs. the pull to use inside information for a new employer or the state.",zh:"保密义务与利用内部信息服务于新雇主或国家的诱惑之间的张力。"} ],
    scenes:[
      { sp:"Alicia Florrick", t:"What are the damages? Loss of consortium." },
      { sp:"Alicia Florrick", t:"You worried about attorney-client privilege?" },
      { sp:"Will Gardner", t:"The privilege survives death." },
      { sp:"Will Gardner", t:"With some exceptions." },
      { sp:"Peter Florrick", t:"Which leaves open a Supreme Court seat." },
      { sp:"Peter Florrick", t:"you'd make a damn good judge." },
      { sp:"Will Gardner", t:"attorney-client privilege may be waived" },
      { sp:"Cary Agos", t:"I can't say anything. It's confidential." },
      { sp:"Cary Agos", t:"When I leave the state's attorney's office, I can't use it to benefit Lockhart Gardner." },
      { sp:"Cary Agos", t:"our client, Ashbaugh, was murdered." },
      { sp:"Kalinda Sharma", t:"You intimidated the Madison County state's attorney on exactly this kind of pot charge." },
      { sp:"Peter Florrick", t:"There is no pot charge!" },
      { sp:"David Lee", t:"You think this is about a dog barking?" },
      { sp:"Kalinda Sharma", t:"You're protecting your detective." }
    ],
    sceneNote:{ en:"The death of a client becomes a prism for privilege: the default rule that confidentiality survives the client's death, the narrow exceptions, and the constant temptation to waive it for advantage. Cary's trapped position — knowing state's-attorney secrets he cannot deploy — shows confidentiality as a cage as much as a shield. Peter's Supreme Court offer reframes Diane as both partner and political prize.", zh:"客户之死成为透视特权的棱镜：默认规则是保密性于客户死后存续、其狭窄例外，以及为谋利而放弃特权的持续诱惑。凯里进退维谷——知晓州检秘密却无法利用——表明保密既是盾也是笼。彼得的最高法院邀约把黛安重塑为既是合伙人又是政治奖赏。" },
    terms:[ "attorney_client_privilege", "loss_of_consortium", "waiver", "confidential", "supreme_court", "intimidation", "settlement", "murder", "privilege" ],
    uk:{ en:"In England legal professional privilege (solicitor-client and litigation privilege) survives the client's death and is waivable, much like the US rule, though the exception for 'furtherance of crime' is narrower. 'Loss of consortium' is not a separate English claim; bereavement and dependency are dealt with under the Fatal Accidents Act 1976 and Law Reform (Miscellaneous Provisions) Act 1934. The UK Supreme Court sits in London as the final appellate court.", zh:"在英格兰，法律职业特权（事务律师—客户特权与诉讼特权）于客户死后存续且可放弃，与美国规则相近，但「促进犯罪」例外更窄。「丧失配偶权」并非英格兰的独立诉因；丧亲与扶养依赖由《1976年致命事故法》及《1934年法律改革（杂项规定）法》处理。英国最高法院设于伦敦，为终审上诉法院。" }
  },
  {
    id:"S04E19", ep:19, title:"The Wheels of Justice", zhTitle:"正义之轮",
    summary:{ en:"A gun-charge case against Sweeney collides with the pending People v. Miles decision: a 'third strike' that could lift a misdemeanor to life. The defense races the 160-day speedy-trial clock, fends off a delayed prosecution strategy, and closes with a not-guilty on the gun charge but a disorderly-conduct conviction. Diane's Supreme Court ambitions loom over it all.", zh:"针对斯威尼的涉枪指控与待决的 People v. Miles 案相撞：该案的「三振」可将轻罪升格为无期。辩方与时间紧迫的 160 天速审期限赛跑，抵御检方拖延策略，终以涉枪无罪、扰乱公共秩序定罪收场。黛安的最高法院野心笼罩全程。" },
    themes:[ {en:"The speedy-trial statute as a hard 160-day clock that can force a trial the defense is unready for.",zh:"速审制定法作为不可通融的 160 天倒计时，可迫使未备妥的辩方仓促受审。"}, {en:"The 'third strike' sentencing multiplier and how a pending appellate decision distorts plea and trial strategy.",zh:"「三振」量刑倍增，以及待决上诉判决如何扭曲认罪与庭审策略。"}, {en:"Evidentiary gates: foundation for exhibits and the proof that the defendant 'did not shoot the gun.'",zh:"证据门槛：物证的基础（foundation）与「被告未开枪」的证明。"} ],
    scenes:[
      { sp:"Alicia Florrick", t:"The prosecution has been dragging their feet on discovery." },
      { sp:"Alicia Florrick", t:"that's a Class 4 felony." },
      { sp:"Judge", t:"You plead this out. Get it out of my court." },
      { sp:"Judge", t:"Two years' probation." },
      { sp:"Will Gardner", t:"The People v. Miles decision will affect Sweeney's sentencing." },
      { sp:"Will Gardner", t:"but it would count as his third strike." },
      { sp:"Alicia Florrick", t:"From a possible misdemeanor to life in prison." },
      { sp:"Alicia Florrick", t:"the speedy trial statute imposes a 160-day time limit" },
      { sp:"Alicia Florrick", t:"the prosecution must go to trial today or release our client." },
      { sp:"Alicia Florrick", t:"Objection, Your Honor. Asked and answered." },
      { sp:"Will Gardner", t:"Objection. Foundation." },
      { sp:"Will Gardner", t:"Defense Exhibit K, Your Honor." },
      { sp:"Will Gardner", t:"The evidence proves that Mr. Sweeney did not shoot the gun, Your Honor. He's innocent." },
      { sp:"Judge Politi", t:"I do find you guilty of disorderly conduct. And I sentence you to a $1,500 fine," }
    ],
    sceneNote:{ en:"The engine of the episode is timing: a speedy-trial statute that, once triggered, forces a trial the defence would rather delay until People v. Miles resolves. The prosecution's 'slow play' is the mirror image. Watch the sentencing arithmetic — a single shot at a party becomes a potential life sentence by strike counting — and the evidentiary discipline (foundation, exhibit marking) that delivers the not-guilty on the gun while leaving disorderly conduct standing.", zh:"本集的引擎是时间：速审制定法一旦触发，便迫使辩方本想拖延至 People v. Miles 落定的案件仓促受审。检方的「慢打」则是镜像。注意量刑算术——派对上的一枪因累计前科竟可能变成无期——以及交付涉枪无罪、却保留扰乱公共秩序定罪的证据纪律（基础、物证标记）。" },
    terms:[ "discovery", "felony", "misdemeanor", "probation", "speedy_trial", "third_strike", "plea_bargain", "foundation", "exhibit", "not_guilty" ],
    uk:{ en:"England has no 'three strikes' life sentence (that is a US, notably California, mechanism), though dangerous-offender provisions can lengthen sentences. There is no fixed 160-day speedy-trial statute; instead custody time limits cap how long a defendant may be held before trial. 'Plea bargaining' is not a formal UK institution, though plea discussions follow the guidelines in R v Goodyear and R v Hayes, and 'not guilty' is the English verdict (Scotland also has 'not proven').", zh:"英格兰无「三振」无期刑（那主要是美国的机制，尤以加州为甚），但危险 offender 条款可加长刑期。英国无固定的 160 天速审制定法，而是以羁押时限约束审判前羁押时长。「认罪协商」并非英国正式制度，但认罪讨论遵循 R v Goodyear 与 R v Hayes 指引；「无罪」为英格兰裁决（苏格兰另有「未能证实」）。" }
  },
  {
    id:"S04E20", ep:20, title:"Rape: A Modern Perspective", zhTitle:"强奸：现代视角",
    summary:{ en:"Rainey Selwin's civil case against her rapist collides with his secret plea bargain, a gag order, her Fifth Amendment silence, and a contempt citation when she tweets. The firm fights illegally-obtained evidence, a quashed subpoena, and a mistrial declared after 'mob justice' in the gallery. The season ends on the question of what a court will and will not let a jury see.", zh:"雷妮·塞尔温针对施暴者的民事案件，与其秘密认罪协商、禁言令、她援引第五修正案沉默，以及因发推文而被判藐视相交织。事务所力战非法取得的证据、被撤销的传票，以及旁听席「私刑正义」后被宣告的无效审判。本季以「法院究竟允许陪审团看见什么」收尾。" },
    themes:[ {en:"Civil vs. criminal forum for sexual assault, and the secret plea bargain that shields the defendant.",zh:"性侵的民事与刑事法院分野，以及庇护被告的秘密认罪协商。"}, {en:"Gag orders, the Fifth Amendment, and contempt as the levers that silence a victim who speaks out.",zh:"禁言令、第五修正案与藐视法庭作为压制发声受害者的杠杆。"}, {en:"Illegally-obtained evidence, the quashed subpoena, and the mistrial born of 'mob justice.'",zh:"非法取得的证据、被撤销的传票，以及由「私刑正义」催生的无效审判。"} ],
    scenes:[
      { sp:"Will Gardner", t:"this is taking place in a civil court and not a criminal court." },
      { sp:"Will Gardner", t:"A rape would seem to be a criminal matter..." },
      { sp:"Opposing Counsel", t:"Objection, Your Honor. Counselor is testifying." },
      { sp:"Rainey Selwin", t:"He raped me and got a plea bargain with the prosecution," },
      { sp:"Judge Parks", t:"I put a gag order in place for exactly that reason." },
      { sp:"Will Gardner", t:"I must insist on my client's Fifth Amendment right against self-incrimination." },
      { sp:"Alicia Florrick", t:"He'll hold you in contempt." },
      { sp:"Judge Parks", t:"Then I must hold you in contempt. Sheriff, please take the witness into custody." },
      { sp:"Alicia Florrick", t:"Rainey Selwin has been held in contempt." },
      { sp:"Judge Parks", t:"This gag order is, and was, content neutral." },
      { sp:"Judge Parks", t:"I cannot admit illegally-obtained evidence." },
      { sp:"Judge Parks", t:"Your subpoena's granted." },
      { sp:"Judge Parks", t:"The plaintiff's subpoena has been quashed." },
      { sp:"Judge Parks", t:"I'm declaring a mistrial." }
    ],
    sceneNote:{ en:"The finale is about visibility: a rape tried in civil court because the criminal system let the defendant 'get a plea bargain'; a victim gagged, then jailed for contempt when she breaks the gag on social media; and a photo that is real but 'illegally obtained' and therefore kept from the jury. The subpoena granted then quashed, and the mistrial born of gallery 'mob justice', leave the season on the question of who controls the narrative a court may hear.", zh:"本季终章关乎「可见性」：因刑事系统让被告「达成认罪协商」而改在民事法院审理的强奸案；被禁言、又在打破社交媒體禁言令后以致藐视入狱的受害者；以及一张真实却「非法取得」、因而拒于陪审团之前的照片。先准后撤的传票，以及旁听席「私刑正义」催生的无效审判，令本季停驻于「谁能控制法院得以听闻的叙事」之问。" },
    terms:[ "gag_order", "fifth_amendment", "contempt", "illegally_obtained_evidence", "subpoena", "class_action", "mistrial", "plea_bargain", "self_incrimination", "deposition" ],
    uk:{ en:"In England a 'gag order' is an injunction restraining publication, enforceable by contempt of court under the Contempt of Court Act 1981; there is no Fifth Amendment, but the right to silence and privilege against self-incrimination protect a witness who refuses to answer. Illegally obtained evidence is not automatically excluded — the judge has a discretion under Police and Criminal Evidence Act 1984 s.78 to exclude if its admission would adversely affect fairness. 'Class actions' became possible in England via representative proceedings and the Competition Act regime, and a 'mistrial' corresponds to a discharged jury or stayed proceedings.", zh:"在英格兰，「禁言令」为限制发表的禁令，可依据《1981年藐视法庭法》以藐视法庭强制执行；无第五修正案，但沉默权与不自证其罪特权保护拒绝作答的证人。非法取得的证据并非自动排除——法官依《1984年警察与刑事证据法》第78条拥有裁量权，若采纳将损害公平则可排除。「集体诉讼」在英国经代表诉讼与《竞争法》机制成为可能；「无效审判」对应解散陪审团或中止程序。" }
  },

  /* --- end of episodes --- */
];

